CREATE TABLE IF NOT EXISTS `dim_account` (
  `account_id` largeint NOT NULL COMMENT "Internal ID (ACCT_ID)",
  `account_number` varchar(64) NOT NULL COMMENT "Public Account Number",
  `customer_id` largeint NOT NULL COMMENT "Link to Customer details in dim_customer",
  `account_name` varchar(255) NULL COMMENT "Account name/title",
  `product_category` varchar(50) NULL COMMENT "Product Category",
  `product_sub_category` varchar(50) NULL COMMENT "Product Sub-Category",
  `legacy_account_number` varchar(64) NULL COMMENT "Legacy System Account Number",
  `product_id` varchar(64) NULL COMMENT "Product Key",
  `branch_id` int NULL COMMENT "Branch where the account is held/opened/serviced",
  `currency_id` int NULL COMMENT "Base Currency of the account",
  `opening_authorizer_id` int NULL,
  `record_status` varchar(20) NULL COMMENT "Active, Dormant, Closed, Frozen",
  `current_risk_id` int NULL,
  `previous_risk_id` int NULL,
  `status_change_date` date NULL,
  `current_balance` decimal(18,2) NULL COMMENT "Current Account Balance",
  `available_balance` decimal(18,2) NULL COMMENT "Available Balance for Withdrawal/Use",
  `credit_limit` decimal(18,2) NULL COMMENT "Credit Limit Amount",
  `overdraft_limit` decimal(18,2) NULL COMMENT "Overdraft Limit Amount",
  `pending_modification_flag` tinyint NULL,
  `auto_reclassification_flag` tinyint NULL,
  `account_opening_date` date NULL,
  `last_kyc_review_date` date NULL,
  `scheduled_review_date` date NULL,
  `authorization_timestamp` datetime NULL,
  `interest_accrual_frequency` varchar(20) NULL,
  `statement_frequency` varchar(20) NULL,
  `user_id` int NULL COMMENT "User who created/modified the record",
  `created_by` varchar(50) NULL COMMENT "Created by User",
  `last_updated_ts` datetime NULL COMMENT "Last Updated Timestamp",
  INDEX idx_acct_status (`record_status`) USING INVERTED,
  INDEX idx_acct_prod_cat (`product_category`) USING INVERTED,
  INDEX idx_acct_open_dt (`account_opening_date`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`account_id`, `account_number`, `customer_id`)
DISTRIBUTED BY HASH(`customer_id`) BUCKETS 16
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"compression" = "ZSTD",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
