CREATE TABLE IF NOT EXISTS `dim_card` (
  `card_id` int NOT NULL COMMENT "Source system auto-increment ID",
  `reference` varchar(40) NOT NULL COMMENT "Unique card request reference number",
  `account_number` varchar(20) NULL COMMENT "Linked bank account number",
  `customer_id_external` varchar(60) NULL COMMENT "Core banking customer ID (custid)",
  `customer_rim_number` varchar(60) NULL COMMENT "Customer RIM/relationship number",
  `customer_name` varchar(60) NULL,
  `customer_short_name` varchar(30) NULL,
  `customer_category` varchar(10) NULL COMMENT "Customer category code",
  `phone` varchar(20) NULL,
  `email` varchar(100) NULL,
  `national_id` varchar(255) NULL,
  `pan_masked` varchar(100) NULL COMMENT "Masked/tokenised card PAN — must never contain full card number",
  `bin` varchar(100) NULL COMMENT "Bank Identification Number (first 6-8 digits of card)",
  `card_expiry_date` varchar(10) NULL COMMENT "Card expiry in MM/YY format",
  `channel_id` varchar(50) NULL COMMENT "Channel through which the card was requested",
  `originating_branch` varchar(10) NULL COMMENT "Branch that initiated the card issuance request",
  `collecting_branch` varchar(10) NULL COMMENT "Branch designated for card collection by customer",
  `status` varchar(20) NULL COMMENT "Current card status (e.g., ACTIVE, BLOCKED, EXPIRED)",
  `stage` varchar(15) NULL COMMENT "Production pipeline stage (e.g., PRINTING, DISPATCHED, ISSUED)",
  `ubx_status` varchar(20) NULL COMMENT "UBX/Switch status: LINKED, ACTIVATED, INITIATED, PIN_CHANGED, PIN_ISSUED",
  `response_code` varchar(15) NULL COMMENT "Core banking response code for the card request",
  `reject_reason` varchar(250) NULL COMMENT "Reason for rejection if issuance was denied",
  `is_allowed` varchar(5) NULL COMMENT "Y=Card issuance approved, N=Blocked",
  `allow_multiple` varchar(5) NULL COMMENT "Y=Multiple active cards permitted for this customer",
  `charge` int NULL COMMENT "Card issuance fee amount (in local currency minor units)",
  `is_charged` tinyint NULL COMMENT "1=Issuance fee has been collected",
  `created_date` datetime NULL,
  `approver1_date` datetime NULL,
  `approver2_date` datetime NULL,
  `dispatched_date` datetime NULL,
  `hq_received_date` datetime NULL,
  `received_from_printing_date` datetime NULL,
  `issued_date` datetime NULL,
  `created_by` varchar(13) NULL,
  `approver1` varchar(13) NULL,
  `approver2` varchar(13) NULL,
  `dispatched_by` varchar(13) NULL,
  `hq_received_by` varchar(13) NULL,
  `issued_by` varchar(13) NULL,
  `received_from_printing` varchar(100) NULL COMMENT "Printing house reference",
  `saved_to_cbs` varchar(100) NULL COMMENT "Core banking system sync status",
  `gen_pan_attempt` int NULL COMMENT "Number of PAN generation attempts (fraud indicator)",
  INDEX idx_card_status (`status`) USING INVERTED,
  INDEX idx_card_stage (`stage`) USING INVERTED,
  INDEX idx_card_ubx_status (`ubx_status`) USING INVERTED,
  INDEX idx_card_originating_branch (`originating_branch`) USING INVERTED,
  INDEX idx_card_is_charged (`is_charged`) USING INVERTED,
  INDEX idx_card_channel (`channel_id`) USING INVERTED,
  INDEX idx_card_account (`account_number`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`card_id`, `reference`)
DISTRIBUTED BY HASH(`card_id`) BUCKETS 4
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"compression" = "ZSTD",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
