"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
CREATE TABLE IF NOT EXISTS `dim_charges_config` (
  `charge_id` largeint NOT NULL COMMENT "CHRG_ID — Primary key",
  `charge_code` varchar(10) NOT NULL COMMENT "CHRG_CD — Unique charge mnemonic (e.g. WDL_FEE)",
  `charge_type` varchar(10) NULL COMMENT "CHRG_TY — Charge category (FLAT, PCTG, TIERD)",
  `charge_name` varchar(100) NULL COMMENT "CHRG_NM — Human-readable charge name",
  `charge_description` varchar(100) NULL COMMENT "CHRG_DESC — Full English description of the charge rule",
  `charge_description_local` varchar(200) NULL COMMENT "CHRG_DESC_LOCAL — Description in local language (Swahili)",
  `tier_type` varchar(10) NULL COMMENT "TIER_TY — Tiering logic: FLAT, SLAB, STEP",
  `calculation_basis` varchar(10) NULL COMMENT "CALC_BASIS_TY — Basis: TXN_AMT, BAL, COUNT",
  `charge_amount` decimal(18,6) NULL COMMENT "CHRG_AMT — Flat fee amount in account currency",
  `charge_percentage` decimal(18,6) NULL COMMENT "CHRG_PCT — Percentage fee",
  `tier_calculation_basis` varchar(10) NULL COMMENT "TIER_CALC_BASIS_TY — Tier evaluation: CUMULATIVE vs INCREMENTAL",
  `rate_quote_method` varchar(10) NULL COMMENT "RATEQUOT_METHOD_CD — Rate convention: ANNUL vs PERIOD",
  `rate_calculation_basis` varchar(24) NULL COMMENT "RATE_CALC_BASIS_CD — Day-count basis: ACT/ACT, ACT/360",
  `settlement_option` char(1) NULL COMMENT "SETLMNT_OPTN — How fee is settled",
  `settlement_option_type_1` varchar(10) NULL COMMENT "SETLMNT_OPTN1_TY — Settlement option variant 1",
  `settlement_option_type_2` varchar(10) NULL COMMENT "SETLMNT_OPTN2_TY — Settlement option variant 2",
  `default_settlement_option_type` varchar(10) NULL COMMENT "DEF_SETLMNT_OPTN_TY — Default settlement option type",
  `settlement_option_code` varchar(10) NULL COMMENT "SETLMNT_OPTN_CD — Coded settlement option (OWN, DEBIT)",
  `charge_settlement_method` varchar(10) NULL COMMENT "CHRG_SETTMNT_MTHD — Mechanism for settling the charge",
  `frequency_number` int NULL COMMENT "FREQ_NO — Numeric component of charge frequency",
  `frequency_day` int NULL COMMENT "FREQ_DD — Day of month for periodic charge posting",
  `frequency_month` int NULL COMMENT "FREQ_MM — Month interval for sub-annual charges",
  `frequency_code` varchar(10) NULL COMMENT "FREQ_CD — Frequency unit: MNTH, WEEK, YEAR, DILY",
  `min_balance_waiver_amount` decimal(18,2) NULL COMMENT "MIN_BAL_WAIVER_AMT — Minimum balance below which fee is waived",
  `balance_basis_type` varchar(10) NULL COMMENT "BAL_BASIS_TY — Balance type for waiver check: LEDGER, CLEARED, AVG",
  `waive_option` varchar(10) NULL COMMENT "WAIVE_OPTION_CD — Whether charge can be waived: NO, AUTH, AUTO",
  `exemption_balance_basis` varchar(10) NULL COMMENT "EXEMP_BAL_BASIS_CD — Balance type for exemption threshold check",
  `exemption_balance_threshold` decimal(18,2) NULL COMMENT "EXEMP_BAL_THRESHOLD — Balance above which customer is exempt",
  `min_amount_per_occurrence` decimal(18,2) NULL COMMENT "MIN_AMT_PER_OCCURRENCE — Minimum fee per single charge event (floor)",
  `max_amount_per_occurrence` decimal(18,2) NULL COMMENT "MAX_AMT_PER_OCCURRENCE — Maximum fee per single charge event (cap)",
  `min_amount_per_period` decimal(18,2) NULL COMMENT "MIN_AMT_PER_PD — Minimum fee per charge period",
  `max_amount_per_period` decimal(18,2) NULL COMMENT "MAX_AMT_PER_PD — Maximum fee per charge period",
  `absolute_max_amount` decimal(18,2) NULL COMMENT "ABSOLUTE_MAX_AMT — Hard ceiling on total fee",
  `max_amount_year_to_date` decimal(18,2) NULL COMMENT "MAX_AMT_YTD — Year-to-date cumulative fee cap",
  `free_items_per_day` int NULL COMMENT "FREE_ITEMS_PER_DAY — Free transactions per day before charge applies",
  `excess_per_day_option_code` varchar(10) NULL COMMENT "EXCESS_PER_DAY_OPTN_CD — Handling option for excess daily transactions",
  `free_items_per_period` int NULL COMMENT "FREE_ITEMS_PER_PD — Free transactions per charge period",
  `excess_per_period_option_code` varchar(10) NULL COMMENT "EXCESS_PER_PD_OPTN_CD — Handling option for excess period transactions",
  `grace_days` int NULL COMMENT "GRACE_DAYS — Grace period in days before charge kicks in",
  `days_in_year` int NULL COMMENT "DAYS_IN_YR — Day-count convention (360 or 365)",
  `fee_cycle_period` int NULL COMMENT "FEE_CYCLE_PERIOD — Length of the fee cycle in days",
  `min_period_days` int NULL COMMENT "MIN_PREIOD_DAY — Minimum days in period for charge to apply",
  `commencement_date_option_code` varchar(10) NULL COMMENT "COMNCMNT_DT_OPTN_CD — Commencement date option code",
  `commencement_from_date` date NULL COMMENT "COMNCMNT_FROM_DT — Commencement start date",
  `commencement_to_date` date NULL COMMENT "COMNCMNT_TO_DT — Commencement end date",
  `include_start_date_flag` char(1) NULL COMMENT "INCLUDE_STRT_DT_FG — Y/N include start date in period",
  `income_gl_account` varchar(64) NULL COMMENT "INCOME_GL_ACCT_NO — GL account where fee income is booked",
  `unearned_gl_account` varchar(64) NULL COMMENT "UNEARN_GL_ACCT_NO — GL for deferred/unearned fee income",
  `income_suspense_gl_account` varchar(64) NULL COMMENT "INCOME_SUSP_GL_ACCT_NO — Suspense GL pending final allocation",
  `calculation_trigger` varchar(10) NULL COMMENT "CALC_TRIGGER_CD — Trigger: EVENT, PERIODIC, MANUAL",
  `calculation_frequency_code` varchar(10) NULL COMMENT "CALC_FREQ_CD — Frequency unit for periodic calculation",
  `calculation_frequency_number` int NULL COMMENT "CALC_FREQ_NO — Numeric interval for calculation frequency",
  `earning_method` varchar(10) NULL COMMENT "EARN_METHOD_CD — Revenue recognition: IMM (immediate), AMORT",
  `amortisation_method` varchar(10) NULL COMMENT "AMORTISATION_METH_CD — Amortisation method for deferred fees",
  `earning_business_unit` varchar(20) NULL COMMENT "EARN_BU — Business unit earning the fee income",
  `period_type_code` varchar(10) NULL COMMENT "PERIOD_TY_CD — Period type: CALENDAR, FISCAL, ROLLING",
  `period_type_frequency_code` varchar(10) NULL COMMENT "PERIOD_TY_FREQ_CD — Period type frequency unit code",
  `period_type_frequency_number` int NULL COMMENT "PERIOD_TY_FREQ_NO — Period type frequency numeric interval",
  `charge_scope` varchar(10) NULL COMMENT "CHRG_SCOPE — Scope: ACCT, CUST, PROD",
  `tenor_frequency_code` varchar(10) NULL COMMENT "TENOR_FREQ_CD — Tenor frequency code for product-level config",
  `external_rule_set_id` int NULL COMMENT "EXT_RULE_SET_ID — External pricing engine rule set reference",
  `balance_action_code` varchar(10) NULL COMMENT "BAL_ACTION_CD — Action on balance when charge fires: DEBIT, CREDIT",
  `posting_frequency_code` varchar(10) NULL COMMENT "POSTING_FREQ_CD — Frequency unit for GL posting",
  `posting_frequency_number` int NULL COMMENT "POSTING_FREQ_NO — Numeric interval for posting frequency",
  `exempt_customers_with_loan` char(1) NULL COMMENT "EXEMPT_CUST_WITH_LN — Y/N: loan holders exempt from this charge",
  `exempt_customers_with_td` char(1) NULL COMMENT "EXEMPT_CUST_WITH_TD — Y/N: term deposit holders exempt",
  `prorate_first_cycle_flag` char(1) NULL COMMENT "PRO_RATE_FIRST_CYCLE_FG — Y/N: first partial period is prorated",
  `channel_id` int NULL COMMENT "CHANNEL_ID — FK to dim_channel (ATM, Mobile, Branch)",
  `channel_scheme_id` int NULL COMMENT "CHANNEL_SCHEME_ID — Channel pricing scheme ID",
  `bank_cost` decimal(18,6) NULL COMMENT "BANK_COST — Internal cost to bank; net_fee = charge_amount - bank_cost",
  `effective_date` datetime NULL COMMENT "EFFECTIVE_DT — Date from which rule is active (point-in-time key)",
  `record_status` varchar(20) NULL COMMENT "REC_ST — A=Active, I=Inactive; always filter A for live rules",
  `currency_id` int NULL COMMENT "CRNCY_ID — FK to dim_currency",
  `user_id` varchar(50) NULL COMMENT "USER_ID — Last user to modify this rule",
  `created_date` datetime NULL COMMENT "CREATE_DT — Date the charge rule was first created",
  `sys_create_timestamp` datetime NULL COMMENT "SYS_CREATE_TS — Precise system creation timestamp",
  `created_by` varchar(50) NULL COMMENT "CREATED_BY — Username who originally created the rule",
  `etl_load_date` datetime NULL COMMENT "ETL-added — Airflow task execution timestamp",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL-added — Airflow batch/job ID for lineage",
  INDEX idx_charge_record_status (`record_status`) USING INVERTED,
  INDEX idx_charge_type (`charge_type`) USING INVERTED,
  INDEX idx_charge_scope (`charge_scope`) USING INVERTED,
  INDEX idx_charge_effective_date (`effective_date`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`charge_id`, `charge_code`)
DISTRIBUTED BY HASH(`charge_id`) BUCKETS 4
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"compression" = "ZSTD",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
