CREATE TABLE IF NOT EXISTS `dim_collateral` (
  `collateral_id` bigint NOT NULL COMMENT "Unique internal ID for the collateral (PK)",
  `collateral_reference_number` varchar(35) NOT NULL COMMENT "Unique business reference for the collateral",
  `customer_id` bigint NOT NULL COMMENT "FK to dim_customer",
  `collateral_type_id` bigint NOT NULL COMMENT "FK to collateral type dimension",
  `credit_application_id` bigint NULL COMMENT "FK to fact_credit_applications",
  `collateral_issuer_id` bigint NULL COMMENT "FK to issuing institution",
  `rating_agency_id` bigint NULL COMMENT "FK to rating agency",
  `address_id` bigint NULL COMMENT "FK to address dimension",
  `currency_id` bigint NOT NULL COMMENT "Currency the collateral is valued in — FK to dim_currency",
  `collateral_description` varchar(200) NOT NULL COMMENT "Primary description of the collateral asset",
  `collateral_description_2` varchar(200) NULL COMMENT "Secondary/additional description",
  `alternate_description` varchar(100) NULL COMMENT "Alternate short description",
  `unit_code` varchar(10) NULL COMMENT "Unit of measurement for the asset",
  `number_of_units` decimal(38,10) NULL COMMENT "Number of units of the collateral asset",
  `collateral_cost` decimal(38,10) NULL COMMENT "Original acquisition cost of the asset",
  `collateral_market_value` decimal(38,10) NULL COMMENT "Current market value of the asset",
  `lending_percentage` decimal(38,10) NULL COMMENT "Percentage of market value the bank will lend against",
  `lending_value` decimal(38,10) NULL COMMENT "Computed lending value (market value * lending pct)",
  `loan_to_value_ratio` decimal(38,10) NULL COMMENT "Loan balance divided by collateral value",
  `cumulative_lien_amount` decimal(38,10) NULL COMMENT "Total lien/hold amount on this collateral",
  `insured_amount` decimal(38,10) NULL COMMENT "Amount covered by insurance policy",
  `collateral_rating` decimal(38,10) NULL COMMENT "Credit/quality rating of the collateral",
  `collateral_issue_date` date NULL COMMENT "Date the collateral was issued",
  `collateral_expiry_date` date NULL COMMENT "Date the collateral expires",
  `verified_date` date NULL COMMENT "Date the collateral was verified by the bank",
  `rating_date` date NULL COMMENT "Date the collateral rating was assigned",
  `valuation_date` date NULL COMMENT "Date the collateral was last valued",
  `valuation_expiry_date` date NULL COMMENT "Date the current valuation expires",
  `next_review_date` date NULL COMMENT "Scheduled next review date",
  `expiry_date` date NULL COMMENT "General expiry date (e.g. for guarantees)",
  `renewal_date` date NULL COMMENT "Date the collateral/policy is due for renewal",
  `registration_date` date NULL COMMENT "Date the collateral was registered",
  `policy_number` varchar(60) NULL COMMENT "Insurance policy number",
  `insurance_company` varchar(60) NULL COMMENT "Name of the insurance company",
  `policy_details` varchar(100) NULL COMMENT "Summary of insurance policy details",
  `registration_number` varchar(30) NULL COMMENT "Official registration number of the asset",
  `registration_name` varchar(100) NULL COMMENT "Name under which the asset is registered",
  `valuation_report_reference` varchar(60) NULL COMMENT "Reference number of the valuation report",
  `valuer` varchar(60) NULL COMMENT "Name of the valuer who conducted the assessment",
  `valuer_registration_number` varchar(30) NULL COMMENT "Official registration number of the valuer",
  `guarantee_issuer` varchar(30) NULL COMMENT "Name of the guarantee issuer",
  `charge_settlement_account` varchar(60) NULL COMMENT "Account used for charge/tax settlement",
  `has_other_facilities` char(1) NOT NULL COMMENT "Y if collateral is used for other facilities",
  `is_jointly_owned` char(1) NULL COMMENT "Y if the asset is jointly owned",
  `record_status` char(1) NOT NULL COMMENT "Record status: A=Active, I=Inactive, D=Deleted",
  `created_date` date NOT NULL COMMENT "Date the collateral record was created in source",
  `user_id` bigint NULL,
  `created_by` varchar(24) NOT NULL COMMENT "User ID who created the record",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking"
) ENGINE=OLAP
UNIQUE KEY(`collateral_id`, `collateral_reference_number`)
COMMENT 'Dimension table of collateral assets linked to credit applications and customers. Source: STAGING.COLLATERAL (Oracle CBS).'
DISTRIBUTED BY HASH(`collateral_id`) BUCKETS 16
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"bloom_filter_columns" = "collateral_type_id, credit_application_id, record_status, collateral_reference_number, customer_id, etl_load_date, currency_id",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"store_row_column" = "true",
"row_store_page_size" = "16384",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
CREATE TABLE IF NOT EXISTS `dim_collateral_type` (
  `collateral_type_id` bigint NOT NULL COMMENT "Unique internal ID for the collateral type (PK)",
  `collateral_type_code` varchar(10) NOT NULL COMMENT "Unique short code for the collateral type",
  `collateral_category_code` varchar(10) NOT NULL COMMENT "Category grouping e.g. Cash, Property, Guarantee",
  `collateral_type_description` varchar(350) NOT NULL COMMENT "Full description of the collateral type",
  `collateral_type_description_local` varchar(700) NULL COMMENT "Description in local language/script",
  `lending_percentage` decimal(38,10) NOT NULL COMMENT "Standard percentage of value the bank will lend against",
  `max_lending_percentage` decimal(38,10) NULL COMMENT "Maximum allowable lending percentage",
  `depreciation_rate` decimal(13,10) NULL COMMENT "Annual depreciation rate applied to the asset",
  `max_age` bigint NULL COMMENT "Maximum allowable age of the asset",
  `max_age_validation_option` varchar(10) NULL COMMENT "Rule applied when max age is breached",
  `revaluation_frequency_code` varchar(10) NULL COMMENT "Frequency unit for revaluation e.g. Monthly, Annual",
  `revaluation_frequency_value` bigint NULL COMMENT "Numeric interval for revaluation",
  `revaluation_method_code` varchar(10) NULL COMMENT "Method used for revaluation",
  `auto_revaluation_flag` char(1) NULL COMMENT "Y if system auto-revalues this collateral type",
  `review_frequency_code` varchar(10) NULL COMMENT "Frequency unit for review e.g. Quarterly",
  `review_frequency_value` bigint NULL COMMENT "Numeric interval for review",
  `measurement_unit_code` varchar(10) NULL COMMENT "Unit of measurement e.g. SQM, Units",
  `reference_number_prefix` varchar(10) NULL COMMENT "Prefix used when generating collateral reference numbers",
  `next_sequence_number` bigint NULL COMMENT "Next available sequence number for reference generation",
  `generates_contingent_entry` char(1) NULL COMMENT "Y if pledging generates a contingent GL entry",
  `contingent_account_number` varchar(60) NULL COMMENT "GL account for contingent entries",
  `contra_contingent_account` varchar(60) NULL COMMENT "Contra GL account for contingent entries",
  `new_collateral_business_model_id` bigint NULL COMMENT "Business model ID for new collateral",
  `review_collateral_business_model_id` bigint NULL COMMENT "Business model ID for reviewed collateral",
  `repo_fa_classification_id` bigint NULL COMMENT "Fixed asset classification for repo collateral",
  `repo_asset_branch_option` varchar(10) NULL COMMENT "Branch option for repo asset handling",
  `specific_branch_id` bigint NULL COMMENT "Specific branch linked to this collateral type",
  `allow_multi_facility_pledging` char(1) NULL COMMENT "Y if collateral can be pledged across multiple facilities",
  `is_cash_convertible` char(1) NULL COMMENT "Y if the asset can be quickly converted to cash",
  `default_customer_primary_address` char(1) NULL COMMENT "Y if customer primary address is used by default",
  `record_status` char(1) NOT NULL COMMENT "Record status: A=Active, I=Inactive, D=Deleted",
  `created_date` date NOT NULL COMMENT "Date the collateral type record was created in source",
  `user_id` bigint NULL,
  `created_by` varchar(24) NOT NULL COMMENT "User ID who created the record",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking"
) ENGINE=OLAP
