CREATE TABLE IF NOT EXISTS `dim_gl_mapper_old` (
  `ledger_number` varchar(20) NOT NULL COMMENT "GL ledger code — join to dim_general_ledger.ledger_number",
  `gl_account_name` varchar(200) NULL COMMENT "GL account description from source system",
  `gl_category_code` varchar(20) NULL COMMENT "e.g. ASS, LIAB, IINC, IEXP, NIINC, NIEXP, CAP, CONT_ASS, CONT_LIAB",
  `record_status` char(1) NULL COMMENT "A=Active, I=Inactive",
  `bs_pl` char(2) NULL COMMENT "BS=Balance Sheet, PL=Profit & Loss",
  `financial_statement_section` varchar(30) NULL COMMENT "ASSETS | LIABILITIES | SHAREHOLDERS FUNDS | INTEREST INCOME | INTEREST EXPENSE | NON FUNDED INCOME | OPERATING EXPENSES | CORPORATE TAX",
  `note_details` varchar(100) NULL COMMENT "Note-level description from GL mapping dictionary",
  `note_group` varchar(100) NULL COMMENT "Mid-level grouping e.g. Term Loans, Call Deposits, Saving Deposits",
  `note_category` varchar(100) NULL COMMENT "Category e.g. Loans and Advances, CASA, Fixed Deposits, Costs of Risk",
  `fs_line_items` varchar(100) NULL COMMENT "Financial statement line e.g. Customer Loans, Customer Deposits, Interest Income",
  `applicable_product_categories` varchar(20) NULL COMMENT "Pipe-separated product category codes e.g. LN, DP, TDEP, ILC, OUTGUAR",
  `matched_product_ids` varchar(200) NULL COMMENT "Pipe-separated product IDs matched to this ledger — FK to dim_product.product_id",
  `matched_product_codes` varchar(200) NULL COMMENT "Pipe-separated product codes matched to this ledger",
  `matched_product_names` varchar(1000) NULL COMMENT "Pipe-separated product names matched to this ledger",
  `loan_category` varchar(50) NULL COMMENT "e.g. Business Loans, Micro Loans, Consumer Loans, Staff Loan, Housing Loans, Wastaafu Loans",
  `loan_type` varchar(20) NULL COMMENT "Term Loan | Overdraft",
  `product_group` varchar(20) NULL COMMENT "NPL classification group: Business | Personal | MIC",
  `deposit_category` varchar(30) NULL COMMENT "Saving Deposit | Current Deposit | Fixed Deposit | Digital Deposit",
  `rw_category` varchar(60) NULL COMMENT "Basel risk weight category name e.g. Business Loans, Consumer Loans, Lien loans",
  `risk_weight` varchar(5) NULL COMMENT "Basel risk weight: 0%, 50%, or 100%",
  `risk_weight_num` decimal(5,2) NULL COMMENT "Risk weight as decimal: 0.00, 0.50, or 1.00",
  `bot_sector` varchar(30) NULL COMMENT "BOT economic sector: Personal | Mortgage | Trade & Commerce | Agriculture | Warehousing | Water",
  `index_rate_id` bigint NULL COMMENT "FK to dim_index_rate.index_rate_id",
  `index_rate_code` varchar(20) NULL COMMENT "Index code e.g. 16, 23, 103, 104",
  `index_rate_name` varchar(100) NULL COMMENT "Index name e.g. Business Loan, Micro Credits, Deposit Default Index rate",
  `index_rate_pct` varchar(10) NULL COMMENT "Rate as formatted percentage string e.g. 28.00%",
  `index_rate_num` decimal(10,4) NULL COMMENT "Rate as numeric value e.g. 28.0000",
  `index_effective_date` date NULL COMMENT "Effective date of the assigned index rate",
  `index_currency` varchar(5) NULL COMMENT "Currency of the index rate: TZS | USD | EUR | GBP",
  `mapping_method` varchar(50) NULL COMMENT "How this row was mapped: Direct Match | Prefix Match | Category Rule | GL Name Rule",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
