CREATE TABLE IF NOT EXISTS `dim_product_mapper` (
  `product_id` bigint NOT NULL COMMENT "FK to dim_product.product_id — primary join key",
  `product_code` int NULL COMMENT "Public-facing product code — FK to dim_product.product_code",
  `product_name` varchar(200) NULL COMMENT "Full product name description",
  `product_category_code` varchar(20) NULL COMMENT "Product type: LN, DP, TDEP, ILC, OUTGUAR, INGUAR, IMPCLCTN, EXPCLCTN, ELC",
  `loan_category` varchar(50) NULL COMMENT "Loan portfolio segment: Business Loans | Micro Loans | Consumer Loans | Staff Loan | Housing Loans | Wastaafu Loans | Personal Loans | Agri-Business Loans | Lien Loans | Insurance Loans",
  `loan_type` varchar(20) NULL COMMENT "Term Loan | Overdraft — NULL for non-loan products",
  `product_group` varchar(20) NULL COMMENT "NPL classification group: Business | Personal | MIC — NULL for non-loan products",
  `deposit_category` varchar(30) NULL COMMENT "Saving Deposit | Current Deposit | Fixed Deposit | Digital Deposit — NULL for non-deposit products",
  `rw_category` varchar(60) NULL COMMENT "Basel risk weight category name e.g. Business Loans, Consumer Loans, Lien loans",
  `risk_weight` varchar(5) NULL COMMENT "Basel risk weight: 0%, 50%, or 100% — NULL if not applicable",
  `risk_weight_num` decimal(5,2) NULL COMMENT "Risk weight as decimal for RWA calculations: 0.00, 0.50, or 1.00",
  `bot_sector` varchar(30) NULL COMMENT "BOT economic sector: Personal | Mortgage | Trade & Commerce | Agriculture | Warehousing | Water",
  `index_rate_id` bigint NULL COMMENT "FK to dim_index_rate.index_rate_id",
  `index_rate_code` varchar(20) NULL COMMENT "Index short code e.g. 16, 23, 103, 104",
  `index_rate_name` varchar(100) NULL COMMENT "Index name e.g. Business Loan, Micro Credits, Deposit Default Index rate",
  `index_rate_pct` varchar(10) NULL COMMENT "Rate as formatted string for display e.g. 28.00%",
  `index_rate_num` decimal(10,4) NULL COMMENT "Rate as numeric for calculations e.g. 28.0000",
  `index_effective_date` date NULL COMMENT "Effective date of the assigned index rate",
  `index_currency` varchar(5) NULL COMMENT "Currency of the index rate: TZS | USD | EUR | GBP",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking"
) ENGINE=OLAP
DUPLICATE KEY(`product_id`, `product_code`)
COMMENT 'Product-level classification mapper — extends dim_product with loan/deposit categories, NPL product group, risk weights, BOT sector and index rates.'
DISTRIBUTED BY HASH(`product_id`) BUCKETS 4
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"light_schema_change" = "true",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728"
);
