  `first_name` varchar(100) NULL,
  `middle_name` varchar(100) NULL,
  `last_name` varchar(100) NULL,
  `full_name` varchar(300) NULL COMMENT "Full Name (first + last)",
  `relationship_manager_preferred_name` varchar(255) NULL COMMENT "Name shown to customers",
  `home_branch_id` int NULL COMMENT "Home Branch Key",
