CREATE TABLE IF NOT EXISTS `dim_wakala_agent` (
  `agent_id` largeint NOT NULL COMMENT "Source system ID (USERS.id)",
  `first_name` varchar(255) NULL,
  `middle_name` varchar(255) NULL,
  `last_name` varchar(255) NULL,
  `email` varchar(255) NULL,
  `phone` varchar(255) NULL,
  `national_id` varchar(255) NULL,
  `gender` varchar(255) NULL,
  `date_of_birth` date NULL,
  `nationality` varchar(255) NULL,
  `domicile` varchar(255) NULL,
  `country` varchar(255) NULL,
  `language` varchar(10) NULL,
  `username` varchar(255) NULL COMMENT "Agent login username",
  `user_type` int NULL COMMENT "1=Agent, 2=Operator, 3=Merchant, etc.",
  `is_user_agent` int NULL COMMENT "1=This user is an agent (vs operator)",
  `merchant_id` largeint NULL COMMENT "Linked merchant account ID",
  `branch_code` varchar(255) NULL COMMENT "Assigned branch, link to dim_business_unit",
  `region_id` largeint NULL COMMENT "Link to dim_region",
  `district_id` largeint NULL COMMENT "Link to dim_district",
  `ward_id` largeint NULL,
  `gps_coordinates` varchar(255) NULL,
  `latitude` varchar(300) NULL,
  `longitude` varchar(300) NULL,
  `location` varchar(255) NULL COMMENT "Descriptive location name",
  `house_number` varchar(255) NULL,
  `street` varchar(255) NULL,
  `postal_code` varchar(255) NULL,
  `business_name` varchar(255) NULL,
  `current_business` varchar(255) NULL COMMENT "Description of current business type",
  `business_license` varchar(255) NULL,
  `business_license_expiry_date` date NULL,
  `certificate_of_incorporation` varchar(255) NULL,
  `business_experience` int NULL COMMENT "Years of business experience",
  `form_of_business` int NULL COMMENT "1=Sole Proprietor, 2=Partnership, 3=Company",
  `education_qualification_id` int NULL,
  `names_agency_operators` varchar(255) NULL COMMENT "Names of operators working under this agent",
  `agent_tax_identification_number` varchar(255) NULL,
  `agent_principal` varchar(255) NULL COMMENT "Principal/master agent code (superagent reference)",
  `agent_principal_name` varchar(255) NULL,
  `agent_operator_msisdn` varchar(100) NULL COMMENT "MSISDN of the last logged-in operator",
  `agent_created_at` datetime NULL COMMENT "Date the agent was onboarded",
  `account_number` varchar(255) NULL COMMENT "Agent float/settlement account",
  `till_number` largeint NULL COMMENT "Assigned till/point-of-sale number",
  `pos_control` varchar(255) NULL COMMENT "POS device assignment reference",
  `device_id` varchar(255) NULL COMMENT "Registered device ID",
  `device_name` varchar(255) NULL COMMENT "Device model/name",
  `firebase_token` varchar(100) NULL COMMENT "Push notification token",
  `is_enabled` tinyint NULL COMMENT "1=Account enabled and active",
  `is_account_locked` tinyint NULL COMMENT "1=Account locked due to failed attempts",
  `failed_attempts` int NULL,
  `merchant_ob_user` int NULL COMMENT "1=Merchant on-boarded user type",
  `status` varchar(100) NULL COMMENT "A=Active, I=Inactive, S=Suspended",
  `rec_status` varchar(255) NULL,
  `last_login_time` datetime NULL,
  `last_transaction_time` datetime NULL,
  `last_transaction_reference` varchar(100) NULL,
  `last_transaction_type` varchar(100) NULL,
  `last_pass_changed_date` datetime NULL,
  `closed_date` date NULL COMMENT "Date the agent account was closed",
  `created_date` datetime NULL,
  `last_modified_date` datetime NULL,
  INDEX idx_wakala_branch (`branch_code`) USING INVERTED,
  INDEX idx_wakala_status (`status`) USING INVERTED,
  INDEX idx_wakala_region (`region_id`) USING INVERTED,
  INDEX idx_wakala_district (`district_id`) USING INVERTED,
  INDEX idx_wakala_user_type (`user_type`) USING INVERTED,
  INDEX idx_wakala_enabled (`is_enabled`) USING INVERTED,
  INDEX idx_wakala_merchant (`merchant_id`) USING INVERTED
) ENGINE=OLAP
