CREATE TABLE IF NOT EXISTS `fact_account_audit` (
  `account_id` bigint NULL COMMENT "FK to dim_account",
  `account_number` varchar(60) NULL COMMENT "Customer-facing account number",
  `audit_timestamp` datetime NOT NULL COMMENT "Timestamp of the audit event — partition key",
  `customer_id` bigint NULL COMMENT "FK to dim_customer",
  `product_id` bigint NULL COMMENT "FK to dim_product",
  `branch_id` bigint NULL COMMENT "FK to dim_business_unit",
  `currency_id` bigint NULL COMMENT "FK to dim_currency",
  `risk_class_id` bigint NULL COMMENT "Risk rating at time of audit event",
  `audit_action` char(3) NULL COMMENT "Type of change: INS=Insert, UPD=Update, DEL=Delete",
  `audit_user` varchar(30) NULL COMMENT "User who triggered the audit event",
  `account_name` varchar(100) NULL COMMENT "Account name at the time of the audit event",
  `product_category` varchar(10) NULL COMMENT "Product category at audit time",
  `product_sub_category` varchar(10) NULL COMMENT "Product sub-category at audit time",
  `record_status` char(1) NULL COMMENT "Record status at audit time: A=Active, D=Deleted",
  `status_effective_date` date NULL COMMENT "Date the status became effective",
  `old_account_number` varchar(60) NULL COMMENT "Previous account number if changed",
  `accrual_frequency_code` varchar(10) NULL COMMENT "Interest accrual frequency code at audit time",
  `accrual_frequency_value` bigint NULL COMMENT "Interest accrual frequency interval at audit time",
  `statement_frequency_code` varchar(10) NULL COMMENT "Statement frequency code at audit time",
  `statement_frequency_value` bigint NULL COMMENT "Statement frequency interval at audit time",
  `statement_layout_id` bigint NULL COMMENT "Statement layout ID at audit time",
  `last_review_date` date NULL COMMENT "Last KYC review date at audit time",
  `next_review_date` date NULL COMMENT "Next scheduled review date at audit time",
  `created_date` date NULL COMMENT "Date the original account record was created in source",
  `user_id` varchar(24) NULL COMMENT "User ID who last updated the record",
  `created_by` varchar(24) NULL COMMENT "User ID who created the record",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking"
) ENGINE=OLAP
DUPLICATE KEY(`account_id`, `account_number`, `audit_timestamp`)
COMMENT 'Audit trail fact table capturing all changes to account records. Source: STAGING.ACCOUNT$AUD (Oracle CBS).'
PARTITION BY RANGE(`audit_timestamp`)
(PARTITION p_history VALUES [('0000-01-01 00:00:00'), ('2024-01-01 00:00:00')),
PARTITION p_2024 VALUES [('2024-01-01 00:00:00'), ('2025-01-01 00:00:00')),
PARTITION p_2025 VALUES [('2025-01-01 00:00:00'), ('2026-01-01 00:00:00')),
PARTITION p_2026 VALUES [('2026-01-01 00:00:00'), ('2027-01-01 00:00:00')),
PARTITION p_future VALUES [('2027-01-01 00:00:00'), (MAXVALUE)))
DISTRIBUTED BY HASH(`account_id`) BUCKETS 16
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"bloom_filter_columns" = "account_number, audit_action, record_status, customer_id, audit_user, etl_load_date",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"light_schema_change" = "true",
"store_row_column" = "true",
"row_store_page_size" = "16384",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728"
);
CREATE TABLE IF NOT EXISTS `fact_channel_transactions` (
  `transaction_timestamp` datetime NOT NULL COMMENT "The
   date and time the transaction occurred",
  `transaction_log_id` varchar(100) NULL COMMENT "Primary
  unique identifier for the log entry",
  `source_account_number` varchar(64) NULL COMMENT "The
  account being debited",
  `transaction_reference` varchar(100) NULL COMMENT "Unique
  reference generated by the channel",
  `destination_account_number` varchar(64) NULL COMMENT "The
  receiving account or GL",
  `channel_id` int NULL COMMENT "Link to dim_channel",
  `business_unit_id` int NULL COMMENT "Branch/unit that owns 
  the terminal",
  `core_banking_txn_id` int NULL COMMENT "Link to core       
  banking transaction",
  `core_banking_chg_id` int NULL COMMENT "Link to core     
  banking charge",
  `channel_name` varchar(50) NULL COMMENT "Channel name",
  `client_app_version` varchar(50) NULL COMMENT "Client      
  application version",
  `transaction_code` varchar(50) NULL COMMENT "Internal
  transaction code",
  `transaction_type` varchar(50) NULL COMMENT "Transaction 
  type",
  `transaction_category` varchar(50) NULL COMMENT "Transaction category",
  `transaction_currency` varchar(10) NULL COMMENT "Currency
  code",
  `transaction_summary` varchar(255) NULL COMMENT "Brief   
  description",
  `on_off_us_indicator` varchar(20) NULL COMMENT "On-us or
  off-us indicator",
  `acquirer_bank_code` varchar(20) NULL COMMENT "Acquirer  
  bank code",
  `terminal_id` varchar(100) NULL COMMENT "Terminal
  identifier",
  `advice_flag` varchar(10) NULL COMMENT "Advice flag",
  `access_code` varchar(50) NULL COMMENT "Access code",
  `card_scheme_name` varchar(50) NULL COMMENT "Card scheme",
  `system_trace_audit_no` varchar(100) NULL COMMENT "STAN",
  `transaction_amount` decimal(18,2) NULL COMMENT "Transaction amount",
  `service_fee_amount` decimal(18,2) NULL COMMENT "Service   
  fee",
  `vat_amount` decimal(18,2) NULL COMMENT "VAT amount",
  `excise_duty_amount` decimal(18,2) NULL COMMENT "Excise    
  duty",
  `government_levy_amount` decimal(18,2) NULL COMMENT "Government levy",
  `post_txn_balance` decimal(18,2) NULL COMMENT "Balance   
  after transaction",
  `transaction_result` varchar(20) NULL COMMENT "Result of
  the transaction",
  `response_code` varchar(10) NULL COMMENT "Response code",
  `api_service_code` varchar(50) NULL COMMENT "API service   
  code",
  `record_status` varchar(20) NULL COMMENT "Record status",
  `transaction_details_json` text NULL COMMENT "Transaction  
  details",
  `charge_gl_account` varchar(64) NULL COMMENT "Charge GL    
  account",
  INDEX idx_src_acc (`source_account_number`) USING INVERTED
) ENGINE=OLAP
DUPLICATE KEY(`transaction_timestamp`, `transaction_log_id`, `source_account_number`)
PARTITION BY RANGE(`transaction_timestamp`)
(PARTITION p2018 VALUES [('0000-01-01 00:00:00'), ('2019-01-01 00:00:00')),
PARTITION p2019 VALUES [('2019-01-01 00:00:00'), ('2020-01-01 00:00:00')),
PARTITION p2020 VALUES [('2020-01-01 00:00:00'), ('2021-01-01 00:00:00')),
PARTITION p2021 VALUES [('2021-01-01 00:00:00'), ('2022-01-01 00:00:00')),
PARTITION p2022 VALUES [('2022-01-01 00:00:00'), ('2023-01-01 00:00:00')),
PARTITION p2023 VALUES [('2023-01-01 00:00:00'), ('2024-01-01 00:00:00')),
PARTITION p2024 VALUES [('2024-01-01 00:00:00'), ('2025-01-01 00:00:00')),
PARTITION p2025 VALUES [('2025-01-01 00:00:00'), ('2026-01-01 00:00:00')),
PARTITION p2026 VALUES [('2026-01-01 00:00:00'), ('2027-01-01 00:00:00')),
PARTITION p_future VALUES [('2027-01-01 00:00:00'), (MAXVALUE)))
DISTRIBUTED BY HASH(`transaction_log_id`) BUCKETS 16
