);
CREATE TABLE IF NOT EXISTS `fact_charged_off_loans` (
  `loan_account_number` largeint NOT NULL COMMENT "The primary loan identifier",
  `write_off_date` date NOT NULL COMMENT "Date the accounting write-off occurred",
  `branch_name` varchar(100) NULL COMMENT "Branch responsible for the original loan",
