CREATE TABLE IF NOT EXISTS `fact_credit_applications` (
  `application_id` bigint NOT NULL COMMENT "Unique internal ID for the credit application (PK)",
  `application_date` date NOT NULL COMMENT "Date the application was submitted — partition key",
  `customer_id` bigint NOT NULL COMMENT "FK to dim_customer",
  `branch_id` bigint NOT NULL COMMENT "FK to dim_business_unit",
  `application_reason_id` bigint NOT NULL COMMENT "Reason for the credit request",
  `credit_type_id` bigint NOT NULL COMMENT "Product type e.g. Overdraft, Term Loan",
  `application_product_id` bigint NULL COMMENT "FK to dim_product",
  `portfolio_id` bigint NULL COMMENT "Portfolio grouping e.g. Retail, SME",
  `primary_officer_id` bigint NOT NULL COMMENT "Staff managing the file — FK to dim_user",
  `secondary_officer_id` bigint NULL COMMENT "Co-managing staff member — FK to dim_user",
  `authorizer_id` bigint NULL COMMENT "Approving manager — FK to dim_user",
  `application_reference_number` varchar(60) NOT NULL COMMENT "External/form reference number",
  `currency_id` bigint NOT NULL COMMENT "Requested currency — FK to dim_currency",
  `approved_currency_id` bigint NULL COMMENT "Final approved currency — FK to dim_currency",
  `requested_limit_amount` decimal(38,10) NOT NULL COMMENT "Original amount requested by customer",
  `approved_limit_amount` decimal(38,10) NULL COMMENT "Final limit granted by the bank",
  `requested_term_unit` varchar(10) NOT NULL COMMENT "Requested term unit e.g. Months, Years",
  `requested_term_duration` bigint NULL COMMENT "Length of credit requested",
  `approved_term_unit` varchar(10) NULL COMMENT "Approved term unit",
  `approved_term_duration` bigint NULL COMMENT "Final duration granted",
  `credit_required_date` date NOT NULL COMMENT "Customer desired disbursement date",
  `requested_expiry_date` date NULL COMMENT "Expiry date of the initial request",
  `approved_expiry_date` date NULL COMMENT "Final expiry date granted by the bank",
  `approved_disbursement_date` date NULL COMMENT "Bank confirmed date for credit availability",
  `approval_date` date NULL COMMENT "Date sanctioned by the committee",
  `decline_date` date NULL COMMENT "Date the application was rejected",
  `validity_expiration_date` date NULL COMMENT "Date until which the offer is valid",
  `next_review_date` date NULL COMMENT "Future audit date for this credit",
  `repayment_source_account_id` bigint NULL COMMENT "Source account for loan repayment",
  `fee_settlement_account_id` bigint NULL COMMENT "Account used to pay processing fees",
  `overdraft_account_id` bigint NULL COMMENT "Linked OD account if applicable",
  `disbursement_target_account_id` bigint NULL COMMENT "Account where loan funds will be sent",
  `refinanced_loan_id` bigint NULL COMMENT "If this application is to pay off an old loan",
  `industry_id` bigint NULL COMMENT "Economic sector for risk exposure",
  `risk_class_id` bigint NULL COMMENT "Risk score at time of request",
  `profit_center_id` bigint NULL COMMENT "Financial accountability link",
  `loan_cycle_count` bigint NULL COMMENT "Current iteration of borrowing",
  `credit_utilisation_method` varchar(10) NOT NULL COMMENT "How funds are drawn e.g. Bulk, Tranches",
  `product_combination_logic` varchar(15) NOT NULL COMMENT "Bundle/combo logic for the product",
  `refinance_option_type` varchar(10) NULL COMMENT "Internal logic for refinancing",
  `rejection_reason_id` bigint NULL COMMENT "Why the application was declined",
  `rejection_caution_type_id` bigint NULL COMMENT "Risk warning level",
  `caution_reason_id` bigint NULL COMMENT "Reason for caution flag",
  `pre_approval_id` bigint NULL COMMENT "Reference to a marketing pre-approval",
  `contribution_requirement` varchar(20) NULL COMMENT "Description of customer equity needed",
  `min_contribution_ratio` decimal(18,6) NULL COMMENT "Percentage customer must provide e.g. 0.20 for 20%",
  `contribution_disbursement` varchar(20) NULL COMMENT "Rules on when customer pays their part",
  `is_multi_currency` char(1) NOT NULL COMMENT "Y if the facility involves multiple currencies",
  `is_multi_beneficiary` char(1) NULL COMMENT "Y if multiple parties receive funds",
  `is_policy_exception` char(1) NULL COMMENT "Y if manual override of policy occurred",
  `record_status` char(1) NOT NULL COMMENT "Record status: A=Active, D=Deleted",
  `application_comments` varchar(50) NULL COMMENT "General remarks",
  `internal_notes` varchar(100) NULL COMMENT "Specific internal credit notes",
  `created_date` date NOT NULL COMMENT "Date the application record was created in source",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking",
  `user_id` varchar(24) NULL COMMENT "User ID who last updated the record",
  `created_by` varchar(24) NULL COMMENT "User ID who created the record"
) ENGINE=OLAP
UNIQUE KEY(`application_id`, `application_date`)
COMMENT 'Fact table of credit applications including limits, terms, approvals and risk. Source: STAGING.CREDIT_APPL (Oracle CBS).'
PARTITION BY RANGE(`application_date`)
(PARTITION p_history VALUES [('0000-01-01'), ('2024-01-01')),
