"bloom_filter_columns" = "branch_id, record_status, credit_type_id, portfolio_id, customer_id, risk_class_id, etl_load_date, application_product_id",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"store_row_column" = "true",
