CREATE TABLE IF NOT EXISTS `fact_deposit_account_history` (
  `transaction_date` date NOT NULL COMMENT "Transaction Date (TRAN_DT) — partition key",
  `account_history_id` largeint NOT NULL COMMENT "Internal ID (ACCT_HIST_ID) — PK in source, unique per event",
  `deposit_account_id` largeint NOT NULL COMMENT "FK to dim_deposit_account.deposit_account_id",
  `account_number` varchar(64) NOT NULL COMMENT "Public Account Number",
  `contra_account_number` varchar(64) NULL COMMENT "Contra / Offset Account Number",
  `value_date` date NULL COMMENT "Value Date (effective date for interest accrual)",
  `create_date` date NULL COMMENT "Record Create Date",
  `row_timestamp` datetime NULL COMMENT "Row Timestamp (ROW_TS)",
  `system_create_timestamp` datetime NULL COMMENT "System Create Timestamp (SYS_CREATE_TS)",
  `debit_credit_indicator` varchar(2) NULL COMMENT "D = Debit, C = Credit",
  `event_id` bigint NULL COMMENT "Event Key (links to GL event)",
  `parent_event_id` bigint NULL COMMENT "Parent Event Key",
  `event_journal_id` bigint NULL COMMENT "Event Journal Key",
  `transaction_journal_id` bigint NULL COMMENT "Transaction Journal Key",
  `event_charge_journal_id` bigint NULL COMMENT "Event Charge Journal Key",
  `event_tax_journal_id` bigint NULL COMMENT "Event Tax Journal Key",
  `channel_id` int NULL COMMENT "Origination Channel Key",
  `transaction_memo_type_code` varchar(10) NULL COMMENT "Transaction Memo Type Code",
  `transaction_currency_id` int NULL COMMENT "Transaction Currency Key",
  `transaction_amount` decimal(27,6) NULL COMMENT "Transaction Amount in TXN currency",
  `exchange_rate` decimal(27,12) NULL COMMENT "FX Rate applied",
  `account_currency_id` int NULL COMMENT "Account Base Currency Key",
  `account_amount` decimal(27,6) NULL COMMENT "Transaction Amount in account currency",
  `contra_account_currency_id` int NULL COMMENT "Contra Account Currency Key",
  `contra_account_amount` decimal(27,6) NULL COMMENT "Contra Account Amount",
  `contra_account_type_id` int NULL COMMENT "Contra Account Type Key",
  `total_charge_amount` decimal(27,6) NULL COMMENT "Total Charge Amount",
  `total_tax_amount` decimal(27,6) NULL COMMENT "Total Tax Amount",
  `event_cost_amount` decimal(27,6) NULL COMMENT "Event Cost",
  `charge_id` bigint NULL COMMENT "Charge Definition Key",
  `tax_id` bigint NULL COMMENT "Tax Definition Key",
  `statement_balance` decimal(27,6) NULL COMMENT "Statement Balance after transaction (STMNT_BAL)",
  `statement_balance_secondary` decimal(27,6) NULL COMMENT "Secondary Statement Balance (STMNT_BAL2)",
  `transaction_reference_text` varchar(100) NULL COMMENT "Transaction Reference / Narration",
  `transaction_description` varchar(300) NULL COMMENT "Transaction Description",
  `depositor_payee_name` varchar(100) NULL COMMENT "Depositor / Payee Name",
  `cheque_number` bigint NULL COMMENT "Cheque Number (if applicable)",
  `source_of_funds_id` int NULL COMMENT "Source of Funds Key",
  `origin_branch_id` int NULL COMMENT "Originating Business Unit / Branch",
  `supervisor_id` int NULL COMMENT "Supervisor User Key",
  `originator_id` int NULL COMMENT "Originator User Key",
  `source_user_id` varchar(24) NULL COMMENT "Source System User ID (USER_ID)",
  `created_by_user` varchar(24) NULL COMMENT "Created By User",
  `passbook_updated_flag` char(1) NULL COMMENT "Y/N — passbook updated",
  `record_status` char(1) NULL COMMENT "Source Record Status (REC_ST)",
  `backdate_processing_status` char(1) NULL COMMENT "Backdate Processing Status",
  `source_version_number` int NULL COMMENT "Source row version number",
  INDEX idx_fdah_deposit_account (`deposit_account_id`) USING INVERTED,
  INDEX idx_fdah_account_number (`account_number`) USING INVERTED,
  INDEX idx_fdah_dr_cr (`debit_credit_indicator`) USING INVERTED,
  INDEX idx_fdah_event_id (`event_id`) USING INVERTED,
  INDEX idx_fdah_event_journal (`event_journal_id`) USING INVERTED,
  INDEX idx_fdah_tran_journal (`transaction_journal_id`) USING INVERTED,
  INDEX idx_fdah_channel (`channel_id`) USING INVERTED,
  INDEX idx_fdah_origin_branch (`origin_branch_id`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`transaction_date`, `account_history_id`)
PARTITION BY RANGE(`transaction_date`)
