CREATE TABLE IF NOT EXISTS `fact_deposit_account_summary` (
  `deposit_account_id` bigint NOT NULL COMMENT "Unique internal ID for the deposit account",
  `account_number` varchar(60) NOT NULL COMMENT "Customer-facing account number",
  `last_activity_date` date NOT NULL COMMENT "Date of last transaction or activity — partition key",
  `product_id` bigint NOT NULL COMMENT "Product linked to this account",
  `ledger_balance` decimal(38,10) NOT NULL COMMENT "Current ledger (book) balance",
  `cleared_balance` decimal(38,10) NOT NULL COMMENT "Cleared funds balance",
  `uncleared_balance_1` decimal(38,10) NOT NULL COMMENT "First layer of uncleared funds",
  `uncleared_balance_2` decimal(38,10) NOT NULL COMMENT "Second layer of uncleared funds",
  `reserved_fund` decimal(38,10) NOT NULL COMMENT "Amount reserved/blocked on account",
  `earmarked_fund` decimal(38,10) NOT NULL COMMENT "Amount earmarked for specific purpose",
  `pending_credit_balance` decimal(38,10) NULL COMMENT "Pending credits not yet cleared",
  `pending_debit_balance` decimal(38,10) NULL COMMENT "Pending debits not yet cleared",
  `provision_balance` decimal(38,10) NULL COMMENT "Provision amount held against this account",
  `penal_balance` decimal(38,10) NULL COMMENT "Penalty amount outstanding",
  `prepaid_charge_balance` decimal(38,10) NOT NULL COMMENT "Prepaid charges balance",
  `cumulative_lien_amount` decimal(38,10) NOT NULL COMMENT "Total lien/hold amount on the account",
  `debit_balance_forward` decimal(38,10) NOT NULL COMMENT "Opening debit balance brought forward",
  `credit_balance_forward` decimal(38,10) NOT NULL COMMENT "Opening credit balance brought forward",
  `ledger_balance_forward` decimal(38,10) NOT NULL COMMENT "Opening ledger balance brought forward",
  `cleared_balance_forward` decimal(38,10) NOT NULL COMMENT "Opening cleared balance brought forward",
  `min_ledger_balance` decimal(38,10) NOT NULL COMMENT "Minimum ledger balance in the period",
  `min_cleared_balance` decimal(38,10) NOT NULL COMMENT "Minimum cleared balance in the period",
  `max_ledger_balance` decimal(38,10) NOT NULL COMMENT "Maximum ledger balance in the period",
  `max_cleared_balance` decimal(38,10) NOT NULL COMMENT "Maximum cleared balance in the period",
  `avg_ledger_balance` decimal(38,10) NOT NULL COMMENT "Average ledger balance for the period",
  `avg_cleared_balance` decimal(38,10) NOT NULL COMMENT "Average cleared balance for the period",
  `avg_ledger_balance_per_day` decimal(38,10) NOT NULL COMMENT "Daily average ledger balance",
  `avg_cleared_balance_per_day` decimal(38,10) NOT NULL COMMENT "Daily average cleared balance",
  `min_ledger_balance_date` date NULL COMMENT "Date minimum ledger balance was recorded",
  `min_cleared_balance_date` date NULL COMMENT "Date minimum cleared balance was recorded",
  `max_ledger_balance_date` date NULL COMMENT "Date maximum ledector balance was recorded",
  `max_cleared_balance_date` date NULL COMMENT "Date maximum cleared balance was recorded",
  `avg_balance_date` date NULL COMMENT "Reference date for average balance calculation",
  `debit_turnover` decimal(38,10) NOT NULL COMMENT "Total debit turnover for the period",
  `credit_turnover` decimal(38,10) NOT NULL COMMENT "Total credit turnover for the period",
  `debit_transaction_count` bigint NOT NULL COMMENT "Number of debit transactions",
  `credit_transaction_count` bigint NOT NULL COMMENT "Number of credit transactions",
  `cheque_count` bigint NOT NULL COMMENT "Number of cheques processed",
  `ytd_returns_count` bigint NOT NULL COMMENT "Year-to-date count of returned items",
  `ytd_clearing_returns_count` bigint NOT NULL COMMENT "Year-to-date count of clearing returns",
  `debit_interest_accrued` decimal(38,10) NOT NULL COMMENT "Debit (overdraft) interest accrued to date",
  `credit_interest_accrued` decimal(38,10) NOT NULL COMMENT "Credit interest accrued to date",
  `debit_interest_per_day` decimal(38,10) NOT NULL COMMENT "Daily debit interest amount",
  `credit_interest_per_day` decimal(38,10) NOT NULL COMMENT "Daily credit interest amount",
  `debit_interest_accrued_ptd` decimal(38,10) NOT NULL COMMENT "Debit interest accrued period-to-date",
  `credit_interest_accrued_ptd` decimal(38,10) NOT NULL COMMENT "Credit interest accrued period-to-date",
  `debit_interest_accrued_ytd` decimal(38,10) NOT NULL COMMENT "Debit interest accrued year-to-date",
  `credit_interest_accrued_ytd` decimal(38,10) NOT NULL COMMENT "Credit interest accrued year-to-date",
  `debit_interest_accrued_ltd` decimal(38,10) NOT NULL COMMENT "Debit interest accrued life-to-date",
  `credit_interest_accrued_ltd` decimal(38,10) NOT NULL COMMENT "Credit interest accrued life-to-date",
  `debit_interest_remainder_accrued` decimal(38,10) NULL COMMENT "Fractional remainder debit interest accrued",
  `credit_interest_remainder_accrued` decimal(38,10) NULL COMMENT "Fractional remainder credit interest accrued",
  `debit_interest_remainder_per_day` decimal(38,10) NULL COMMENT "Fractional remainder daily debit interest",
  `credit_interest_remainder_per_day` decimal(38,10) NULL COMMENT "Fractional remainder daily credit interest",
  `credit_interest_paid` decimal(38,10) NULL COMMENT "Credit interest paid out to customer",
  `debit_interest_paid` decimal(38,10) NOT NULL COMMENT "Debit interest collected from customer",
  `debit_interest_charged` decimal(38,10) NULL COMMENT "Debit interest charged in the period",
  `debit_interest_suspended` decimal(38,10) NOT NULL COMMENT "Debit interest suspended (non-performing)",
  `credit_effective_interest_rate` decimal(38,12) NULL COMMENT "Effective annual credit interest rate",
  `debit_effective_interest_rate` decimal(38,12) NULL COMMENT "Effective annual debit/overdraft interest rate",
  `penal_effective_rate` decimal(38,10) NULL COMMENT "Effective penal/penalty interest rate",
  `penal_interest_per_day` decimal(38,10) NULL COMMENT "Daily penal interest amount",
  `charges_applied` decimal(38,10) NULL COMMENT "Total charges applied to the account",
  `total_cost` decimal(38,10) NULL COMMENT "Total cost of the account for the period",
  `total_charges` decimal(38,10) NULL COMMENT "Total charges levied",
  `total_tax` decimal(38,10) NULL COMMENT "Total tax applied",
  `cycle_opening_ledger_balance` decimal(38,10) NULL COMMENT "Ledger balance at start of account cycle",
  `cycle_opening_cleared_balance` decimal(38,10) NULL COMMENT "Cleared balance at start of account cycle",
  `cycle_closing_ledger_balance` decimal(38,10) NULL COMMENT "Ledger balance at end of account cycle",
  `cycle_closing_cleared_balance` decimal(38,10) NULL COMMENT "Cleared balance at end of account cycle",
  `statement_opening_balance` decimal(38,10) NULL COMMENT "Opening balance on the latest statement",
  `statement_count` bigint NULL COMMENT "Number of statements generated",
  `statement_start_date` date NULL COMMENT "Start date of the current statement period",
  `next_statement_date` date NULL COMMENT "Scheduled date for next statement generation",
  `last_deposit_date` date NULL COMMENT "Date of the last credit/deposit",
  `last_deposit_amount` decimal(38,10) NOT NULL COMMENT "Amount of the last deposit",
  `last_withdrawal_date` date NULL COMMENT "Date of the last withdrawal",
  `last_withdrawal_amount` decimal(38,10) NOT NULL COMMENT "Amount of the last withdrawal",
  `last_overdraft_date` date NULL COMMENT "Date account last went into overdraft",
  `delinquent_date` date NULL COMMENT "Date account became delinquent",
  `account_cycle_start_date` date NULL COMMENT "Start date of the current account cycle",
  `account_cycle_end_date` date NULL COMMENT "End date of the current account cycle",
  `current_accrual_date` date NULL COMMENT "Current accrual calculation date",
  `last_accrual_time` datetime NULL COMMENT "Timestamp of the last interest accrual run",
  `last_product_update_date` date NULL COMMENT "Date the product was last changed on account",
  `earliest_backvalue_date` date NULL COMMENT "Earliest back-value date allowed",
  `last_backvalue_date` date NULL COMMENT "Date of the last back-value transaction",
  `next_overdraft_charge_date` date NULL COMMENT "Scheduled date for next overdraft charge",
  `last_provision_date` date NULL COMMENT "Date the last provision entry was made",
  `debit_last_accrual_date` date NULL COMMENT "Last date debit interest was accrued",
  `debit_next_accrual_date` date NULL COMMENT "Next scheduled debit interest accrual date",
  `credit_last_accrual_date` date NULL COMMENT "Last date credit interest was accrued",
  `credit_next_accrual_date` date NULL COMMENT "Next scheduled credit interest accrual date",
  `debit_last_backdated_txn_date` date NULL COMMENT "Date of last backdated debit transaction",
  `credit_last_backdated_txn_date` date NULL COMMENT "Date of last backdated credit transaction",
  `record_status` char(1) NOT NULL COMMENT "Record status: A=Active, I=Inactive, D=Deleted",
  `statistics_update_flag` char(1) NOT NULL COMMENT "Y/N flag indicating stats need refresh",
  `temp_reclassification_status` char(1) NULL COMMENT "Temporary reclassification status flag",
  `accrual_due_flag` char(1) NOT NULL COMMENT "Y/N flag indicating accrual is due",
  `debit_interest_override_flag` char(1) NULL COMMENT "Y/N override flag for debit interest rate",
  `credit_interest_override_flag` char(1) NULL COMMENT "Y/N override flag for credit interest rate",
  `balance_change_flag` char(1) NULL COMMENT "Flag indicating balance changed in this cycle",
  `created_date` date NOT NULL COMMENT "Date the account record was created in source",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking",
  `user_id` varchar(24) NULL COMMENT "User ID who last updated the record",
  `created_by` varchar(24) NULL COMMENT "User ID who created the record"
) ENGINE=OLAP
UNIQUE KEY(`deposit_account_id`, `account_number`, `last_activity_date`)
COMMENT 'Periodic snapshot fact table of deposit account balances, accruals, turnover and control flags. Source: STAGING.DEPOSIT_ACCOUNT_SUMMARY (Oracle CBS).'
PARTITION BY RANGE(`last_activity_date`)
(PARTITION p_history VALUES [('0000-01-01'), ('2024-01-01')),
