  `deposit_ledger` varchar(10) NULL COMMENT "Parent deposit ledger (FK → dim_deposit_account)",
  `deposit_category` varchar(40) NULL COMMENT "Term Deposit | Call / Current | DQA / Savings | etc.",
  `deposit_product` varchar(120) NULL COMMENT "Product description from dim_deposit_account",
  `product_id` int NULL COMMENT "FK → dim_product.product_id",
  `product_code` varchar(10) NULL COMMENT "Product code"
