CREATE TABLE IF NOT EXISTS `fact_deposit_transactions` (
  `deposit_transaction_id` bigint NOT NULL COMMENT "Primary unique id for the transaction entry.",
  `deposit_account_id` bigint NULL COMMENT "Link to dim_account.",
  `transaction_date` datetime NULL COMMENT "Official posting date of the deposit/withdrawal.",
  `account_number` varchar(64) NULL COMMENT "Human-readable account number.",
  `contra_account_number` varchar(64) NULL COMMENT "The offsetting account (e.g., for a transfer).",
  `value_date` datetime NULL COMMENT "Date for interest calculation/accounting value.",
  `transaction_amount` double NULL COMMENT "Amount in the currency of the transaction.",
  `account_currency_amount` double NULL COMMENT "Amount in the account's local currency.",
  `contra_account_amount` double NULL COMMENT "Amount posted to the offsetting account.",
  `total_charges_amount` double NULL COMMENT "Fees charged to the customer for this txn.",
  `total_tax_amount` double NULL COMMENT "Government taxes (Excise/VAT) on the fees.",
  `internal_system_cost` double NULL COMMENT "Internal operational cost of the transaction.",
  `exchange_rate_applied` double NULL COMMENT "FX rate if txn currency differs from acct currency.",
  `post_txn_cleared_balance` double NULL COMMENT "The cleared balance after this transaction.",
  `post_txn_total_balance` double NULL COMMENT "Total balance (including floats/uncollected funds).",
  `debit_credit_indicator` varchar(5) NULL COMMENT "'D' for Withdrawal, 'C' for Deposit.",
  `transaction_narrative` varchar(500) NULL COMMENT "Brief description of the transaction.",
  `transaction_reference` varchar(100) NULL COMMENT "Slip number or external reference.",
  `cheque_number` double NULL COMMENT "Reference for physical cheque deposits.",
  `counterparty_name` varchar(255) NULL COMMENT "Name of the person at the teller or recipient.",
  `memo_type_code` varchar(50) NULL COMMENT "Internal accounting memo classification.",
  `backdate_status` varchar(20) NULL COMMENT "Indicates if the entry was posted in the past.",
  `record_status` varchar(20) NULL COMMENT "Active, Reversed, or Deleted.",
  `passbook_flag` varchar(10) NULL COMMENT "Operational UI flag for physical books. BI=No.",
  `transaction_currency_id` double NULL COMMENT "Refers to dim_currency.",
  `account_currency_id` double NULL COMMENT "Redundant with TXN_CRNCY_ID.",
  `contra_currency_id` double NULL COMMENT "Currency of the offsetting account.",
  `contra_account_type` double NULL COMMENT "Type (GL, Customer, etc.) of the offset account.",
  `channel_id` double NULL COMMENT "Link to dim_channel (Branch, ATM, Mobile).",
  `origin_branch_id` double NULL COMMENT "The branch where the transaction was initiated.",
  `event_type_id` double NULL COMMENT "Type: Cash Deposit, ATM Withdrawal, Transfer, etc.",
  `parent_event_id` double NULL COMMENT "Link to the original txn in case of reversals.",
  `source_of_funds_id` double NULL COMMENT "AML classification (Salary, Business, Gift).",
  `charge_type_id` double NULL COMMENT "Link to dim_charge_config.",
  `tax_type_id` double NULL COMMENT "Link to tax configuration rules.",
  `journal_batch_id` double NULL COMMENT "Link to fact_transaction_journal for the double-entry leg.",
  `event_batch_id` double NULL COMMENT "Groups all legs of a multi-part event.",
  `charge_batch_id` double NULL COMMENT "Link specifically to the fee legs of the txn.",
  `tax_batch_id` double NULL COMMENT "Link specifically to the tax legs of the txn.",
  `maker_user_id` double NULL COMMENT "Staff who captured the transaction.",
  `checker_user_id` double NULL COMMENT "Staff who authorized the transaction.",
  `last_modified_by` varchar(100) NULL COMMENT "Technical audit field.",
  `system_created_by` varchar(100) NULL COMMENT "Use maker_user_id for BI tracking.",
  `system_creation_date` datetime NULL COMMENT "Use TRAN_DT for business reporting.",
  `system_creation_ts` datetime NULL COMMENT "High-precision audit timestamp. BI=No.",
  `row_timestamp` datetime NULL COMMENT "Technical DB system time. BI=No.",
  `record_version` double NULL COMMENT "Technical locking version. BI=No.",
  `cdc_source_table` varchar(128) NULL COMMENT "Source table name from CDC stream.",
  `cdc_scn` varchar(50) NULL COMMENT "Oracle System Change Number.",
  `cdc_operation_type` varchar(10) NULL COMMENT "I=Insert, U=Update, D=Delete.",
  `cdc_operation_ts` varchar(50) NULL COMMENT "Timestamp of the source DB operation.",
  `cdc_current_ts` varchar(50) NULL COMMENT "Kafka ingestion timestamp.",
  `cdc_row_id` varchar(50) NULL COMMENT "Oracle ROWID of the source record.",
  `cdc_username` varchar(100) NULL COMMENT "DB user who performed the change."
) ENGINE=OLAP
UNIQUE KEY(`deposit_transaction_id`, `deposit_account_id`, `transaction_date`)
PARTITION BY RANGE(`transaction_date`)
(PARTITION p_null VALUES [('0000-01-01 00:00:00'), ('1970-01-02 00:00:00')),
PARTITION p2018 VALUES [('1970-01-02 00:00:00'), ('2019-01-01 00:00:00')),
PARTITION p2019 VALUES [('2019-01-01 00:00:00'), ('2020-01-01 00:00:00')),
