CREATE TABLE IF NOT EXISTS `fact_deposit_transactions_enriched` (
  `deposit_transaction_id` bigint NOT NULL COMMENT "PK from fact_deposit_transactions_1",
  `transaction_date` datetime NULL COMMENT "Posting date — partition key",
  `account_number` varchar(64) NULL COMMENT "Masked account number",
  `contra_account_number` varchar(64) NULL COMMENT "Masked contra account number",
  `transaction_reference` varchar(100) NULL COMMENT "Slip / external reference",
  `cheque_number` double NULL COMMENT "Cheque number",
  `transaction_date_day` date NULL COMMENT "DATE(transaction_date)",
  `transaction_year` int NULL COMMENT "YEAR(transaction_date)",
  `transaction_month` int NULL COMMENT "MONTH(transaction_date)",
  `transaction_quarter` int NULL COMMENT "QUARTER(transaction_date)",
  `transaction_day_of_week` int NULL COMMENT "DAYOFWEEK(transaction_date)",
  `value_date` datetime NULL COMMENT "Value date for interest accrual",
  `value_date_lag_days` int NULL COMMENT "DATEDIFF(transaction_date, value_date)",
  `transaction_age_days` int NULL COMMENT "DATEDIFF(CURDATE(), transaction_date)",
  `backdate_status` varchar(20) NULL COMMENT "Backdate indicator",
  `debit_credit_indicator` varchar(5) NULL COMMENT "DR or CR",
  `debit_credit_label` varchar(30) NULL COMMENT "DEBIT / WITHDRAWAL or CREDIT / DEPOSIT",
  `transaction_amount` double NULL COMMENT "Amount in transaction currency",
  `exchange_rate_applied` double NULL COMMENT "FX rate",
  `account_currency_amount` double NULL COMMENT "Amount in account currency",
  `credit_amount` double NULL COMMENT "Amount if CR, else 0",
  `debit_amount` double NULL COMMENT "Amount if DR, else 0",
  `net_flow_amount` double NULL COMMENT "DR positive, CR negative (bank perspective)",
  `contra_account_amount` double NULL COMMENT "Contra account amount",
  `contra_account_type` double NULL COMMENT "Contra account type",
  `total_charges_amount` double NULL COMMENT "Customer charges",
  `total_tax_amount` double NULL COMMENT "Government taxes on fees",
  `internal_system_cost` double NULL COMMENT "Internal operational cost",
  `total_fee_and_tax` double NULL COMMENT "charges + tax combined",
  `post_txn_cleared_balance` double NULL COMMENT "Cleared balance after txn",
  `post_txn_total_balance` double NULL COMMENT "Total balance after txn",
  `uncleared_float_amount` double NULL COMMENT "Total - cleared",
  `journal_batch_id` largeint NULL COMMENT "transaction journal id",
  `transaction_narrative` varchar(500) NULL COMMENT "Transaction description",
  `counterparty_name` varchar(255) NULL COMMENT "Depositor / payee name",
  `memo_type_code` varchar(50) NULL COMMENT "Internal memo classification",
  `event_code` varchar(50) NULL COMMENT "Event code from dim_event",
  `event_description` varchar(255) NULL COMMENT "Event description",
  `event_category_code` varchar(50) NULL COMMENT "Event category code",
  `event_group_code` varchar(50) NULL COMMENT "Event group code",
  `parent_event_id` double NULL COMMENT "Parent event (for reversals)",
  `event_linkage_type` varchar(20) NULL COMMENT "ORIGINAL or REVERSAL / LINKED",
  `income_type` varchar(50) NOT NULL COMMENT "Granular income type (37 values)",
  `income_group` varchar(30) NOT NULL COMMENT "High-level income group (15 values)",
  `bank_income_flag` varchar(30) NOT NULL COMMENT "BANK_INCOME / BANK_EXPENSE / OPERATIONAL",
  `channel_name` varchar(100) NULL COMMENT "Channel name from dim_channel",
  `origin_branch_name` varchar(255) NULL COMMENT "Originating branch",
  `origin_district_id` int NULL COMMENT "District of originating branch",
  `origin_city_id` int NULL COMMENT "City of originating branch",
  `transaction_currency_code` varchar(10) NULL COMMENT "Transaction currency code",
  `transaction_currency_name` varchar(100) NULL COMMENT "Transaction currency name",
  `account_currency_code` varchar(10) NULL COMMENT "Account currency code",
  `account_currency_name` varchar(100) NULL COMMENT "Account currency name",
  `fx_flag` varchar(20) NULL COMMENT "FX TRANSACTION or LOCAL",
  `account_name` varchar(255) NULL COMMENT "Account name from dim_deposit_account",
  `account_opening_date` date NULL COMMENT "Account opening date",
  `account_closed_date` date NULL COMMENT "Account closed date",
  `account_age_at_txn_days` int NULL COMMENT "Account age at time of transaction",
  `customer_id` largeint NULL COMMENT "FK to dim_customer — enables direct join to v_dim_customer",
  `customer_number` varchar(64) NULL COMMENT "Business customer number",
  `customer_name` varchar(255) NULL COMMENT "Customer full name",
  `customer_category` varchar(100) NULL COMMENT "PER, ASSOC, etc.",
  `customer_risk_rating_id` int NULL COMMENT "Customer risk rating key",
  `kyc_level` int NULL COMMENT "KYC compliance level",
  `is_resident_flag` tinyint NULL COMMENT "1 = resident",
  `aml_failed_flag` tinyint NULL COMMENT "1 = AML failure",
  `insider_relationship_flag` tinyint NULL COMMENT "1 = staff/insider",
  `customer_status` varchar(100) NULL COMMENT "Active, Closed, etc.",
  `customer_home_branch` varchar(255) NULL COMMENT "Customer home branch name",
  `product_name` varchar(255) NULL COMMENT "Product name from dim_product",
  `product_type` varchar(50) NULL COMMENT "Product type",
  `product_status` varchar(100) NULL COMMENT "Product record status",
  `product_category_mapped` varchar(50) NULL COMMENT "Mapped product category",
  `source_of_funds_id` double NULL COMMENT "Source of funds key",
  `maker_name` varchar(300) NULL COMMENT "Maker user full name",
  `maker_login` varchar(64) NULL COMMENT "Maker login name",
  `checker_name` varchar(300) NULL COMMENT "Checker user full name",
  `checker_login` varchar(64) NULL COMMENT "Checker login name",
  `maker_checker_status` varchar(30) NULL COMMENT "SEGREGATED / SAME / INCOMPLETE",
  `transaction_record_status_code` varchar(20) NULL COMMENT "Raw status code",
  `transaction_record_status` varchar(100) NULL COMMENT "Status description",
  INDEX idx_fdte_txn_date (`transaction_date_day`) USING INVERTED,
  INDEX idx_fdte_income_type (`income_type`) USING INVERTED,
  INDEX idx_fdte_income_grp (`income_group`) USING INVERTED,
  INDEX idx_fdte_bank_flag (`bank_income_flag`) USING INVERTED,
  INDEX idx_fdte_event_code (`event_code`) USING INVERTED,
  INDEX idx_fdte_acct_num (`account_number`) USING INVERTED,
  INDEX idx_fdte_cust_cat (`customer_category`) USING INVERTED,
  INDEX idx_fdte_prod_cat (`product_category_mapped`) USING INVERTED,
  INDEX idx_fdte_dr_cr (`debit_credit_indicator`) USING INVERTED,
  INDEX idx_fdte_channel (`channel_name`) USING INVERTED,
  INDEX idx_fdte_fx (`fx_flag`) USING INVERTED
) ENGINE=OLAP
