CREATE TABLE IF NOT EXISTS `fact_exchange_rates` (
  `exchange_rate_history_id` largeint NOT NULL COMMENT "Unique surrogate id for each historical rate change.",
  `exchange_rate_pair_id` int NOT NULL COMMENT "Refers
  to the specific currency pair (e.g., USD/TZS).",
  `valid_from_timestamp` datetime NULL COMMENT "The exact  
  moment this rate became active.",
  `exchange_rate_type_id` int NULL COMMENT "e.g., Mid-rate,
  Buying rate, Selling rate, or Revaluation rate.",
  `exchange_rate_value` decimal(18,8) NULL COMMENT "The
  actual rate (e.g., 2650.50 TZS per 1 USD).",
  `inverse_rate_value` decimal(18,8) NULL COMMENT "Precomputed 1/rate for reverse conversions.",
  `valid_to_timestamp` datetime NULL COMMENT "The moment this
   rate was superseded.",
  `spread_percentage` decimal(10,4) NULL COMMENT "Markup   
  between buying/selling vs mid-rate.",
  `rate_source` varchar(50) NULL COMMENT "BOT, Reuters,    
  Manual.",
  `record_status` varchar(20) NULL COMMENT "Active, Expired,
  Deleted.",
  `system_creation_date` date NULL COMMENT "Use            
  valid_from_timestamp for business logic.",
  `system_created_by` varchar(50) NULL COMMENT "Technical  
  audit field.",
  `start_effective_date` date NULL COMMENT "Date-only version
   of valid_from for partition-based queries.",
  `end_effective_date` date NULL COMMENT "Date-only version
  of valid_to for partition-based queries."
) ENGINE=OLAP
UNIQUE KEY(`exchange_rate_history_id`, `exchange_rate_pair_id`, `valid_from_timestamp`)
PARTITION BY RANGE(`valid_from_timestamp`)
(PARTITION p2018 VALUES [('0000-01-01 00:00:00'), ('2019-01-01 00:00:00')),
