PARTITION p2022 VALUES [('2022-01-01 00:00:00'), ('2023-01-01 00:00:00')),
PARTITION p2023 VALUES [('2023-01-01 00:00:00'), ('2024-01-01 00:00:00')),
PARTITION p2024 VALUES [('2024-01-01 00:00:00'), ('2025-01-01 00:00:00')),
