CREATE TABLE IF NOT EXISTS `fact_gl_account_summary` (
  `gl_account_summary_id` bigint NOT NULL COMMENT "Unique internal ID for the GL account summary (PK)",
  `gl_account_id` bigint NOT NULL COMMENT "FK to dim_general_ledger",
  `created_date` date NOT NULL COMMENT "Date the GL summary record was created in source",
  `last_activity_date` datetime NULL COMMENT "Timestamp of last activity on the GL account — partition key",
  `gl_account_number` varchar(60) NOT NULL COMMENT "Human-readable GL account code",
  `currency_id` bigint NOT NULL COMMENT "FK to dim_currency",
  `opening_balance` decimal(38,10) NOT NULL COMMENT "Opening balance for the period",
  `ledger_balance` decimal(38,10) NOT NULL COMMENT "Current ledger balance",
  `avg_ledger_balance` decimal(38,10) NOT NULL COMMENT "Average ledger balance for the period",
  `min_ledger_balance` decimal(38,10) NOT NULL COMMENT "Minimum ledger balance in the period",
  `max_ledger_balance` decimal(38,10) NOT NULL COMMENT "Maximum ledger balance in the period",
  `debit_turnover` decimal(38,10) NOT NULL COMMENT "Total debit turnover for the period",
  `credit_turnover` decimal(38,10) NOT NULL COMMENT "Total credit turnover for the period",
  `debit_count` bigint NOT NULL COMMENT "Number of debit entries for the period",
  `credit_count` bigint NOT NULL COMMENT "Number of credit entries for the period",
  `daily_debit_turnover` decimal(38,10) NULL COMMENT "Debit turnover for the current day",
  `daily_credit_turnover` decimal(38,10) NULL COMMENT "Credit turnover for the current day",
  `daily_debit_count` bigint NULL COMMENT "Number of debit entries for the current day",
  `daily_credit_count` bigint NULL COMMENT "Number of credit entries for the current day",
  `daily_opening_balance` decimal(38,10) NULL COMMENT "Opening balance for the current day",
  `record_status` char(1) NOT NULL COMMENT "Record status: A=Active, I=Inactive, D=Deleted",
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking",
  `user_id` varchar(24) NULL COMMENT "User ID who last updated the record",
  `created_by` varchar(24) NULL COMMENT "User ID who created the record"
) ENGINE=OLAP
UNIQUE KEY(`gl_account_summary_id`, `gl_account_id`, `created_date`)
COMMENT 'Periodic snapshot fact table of GL account balances and turnover. Source: STAGING.GL_ACCOUNT_SUMMARY (Oracle CBS).'
PARTITION BY RANGE(`created_date`)
(PARTITION p_history VALUES [('0000-01-01'), ('2024-01-01')),
PARTITION p_2024 VALUES [('2024-01-01'), ('2025-01-01')),
PARTITION p_2025 VALUES [('2025-01-01'), ('2026-01-01')),
PARTITION p_2026 VALUES [('2026-01-01'), ('2027-01-01')),
PARTITION p_future VALUES [('2027-01-01'), (MAXVALUE)))
DISTRIBUTED BY HASH(`gl_account_summary_id`) BUCKETS 16
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"bloom_filter_columns" = "gl_account_id, record_status, gl_account_number, etl_load_date, currency_id",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"store_row_column" = "true",
"row_store_page_size" = "16384",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
CREATE TABLE IF NOT EXISTS `fact_gl_daily_balance_history` (
  `gl_daily_bal_hist_id` bigint NOT NULL COMMENT "PK — surrogate ID from Oracle GL_DAILY_BAL_HIST_ID",
  `gl_account_summary_id` bigint NOT NULL COMMENT "FK to dws.fact_gl_account_summary (GL_ACCT_SUMMARY_ID)",
  `balance_date` date NOT NULL COMMENT "Balance date — daily grain, partition key (BAL_DT)",
  `gl_account_id` bigint NOT NULL COMMENT "Denormalised FK to dim_general_ledger (GL_ACCT_ID) — avoids join through summary",
  `daily_debit_turnover` decimal(38,10) NULL,
  `daily_credit_turnover` decimal(38,10) NULL,
  `ledger_balance` decimal(38,10) NOT NULL COMMENT "Closing ledger balance at end of day (LEDGER_BAL)",
  `adj_ledger_balance` decimal(38,10) NULL COMMENT "Adjusted/restated ledger balance when applicable (ADJ_LEDGER_BAL) — NULL if no adjustment",
  `is_week_end` char(1) NOT NULL DEFAULT "N" COMMENT "Y if balance_date is a week-end date (WEEK_END_FG)",
  `is_period_end` char(1) NOT NULL DEFAULT "N" COMMENT "Y if balance_date is a monthly period-end date (PERIOD_END_FG)",
  `is_quarter_end` char(1) NOT NULL DEFAULT "N" COMMENT "Y if balance_date is a quarter-end date (QUARTER_END_FG)",
  `is_year_end` char(1) NOT NULL DEFAULT "N" COMMENT "Y if balance_date is a year-end date (YEAR_END_FG)",
  `created_date` date NOT NULL COMMENT "Date the record was created in source (CREATE_DT)",
  `last_activity_date` datetime NULL COMMENT "Timestamp of last source system activity on this row (LAST_ACTIVITY_DT)",
  `etl_load_date` datetime NOT NULL COMMENT "Timestamp of ETL run — use for audit/lineage",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking"
) ENGINE=OLAP
