CREATE TABLE IF NOT EXISTS `fact_gl_transactions` (
  `transaction_history_id` largeint NOT NULL COMMENT "PK — maps to ACCT_HIST_ID",
  `transaction_date` date NOT NULL COMMENT "Partition key — maps to TRAN_DT (system post date)",
  `gl_account_id` largeint NOT NULL COMMENT "maps to GL_ACCT_ID (always negative in source)",
  `gl_account_number` varchar(60) NULL COMMENT "maps to GL_ACCT_NO",
  `account_currency_amount` decimal(38,10) NULL COMMENT "Gross amount in account currency — maps to ACCT_AMT. Do NOT aggregate; use signed_amount.",
  `transaction_amount` decimal(38,10) NULL COMMENT "Transaction currency amount — maps to TXN_AMT",
  `dr_cr_indicator` varchar(2) NULL COMMENT "DR or CR — maps to DR_CR_IND. Used to derive signed_amount in pipeline.",
  `system_running_balance` decimal(38,10) NULL COMMENT "Source system cumulative balance — maps to STMNT_BAL. Do NOT SUM in BI layer.",
  `account_currency_id` largeint NULL COMMENT "Account currency FK — maps to ACCT_CRNCY_ID → dim_currency_cdc",
  `transaction_currency_id` largeint NULL COMMENT "Transaction currency FK — maps to TXN_CRNCY_ID → dim_currency_cdc",
  `contra_account_currency_id` largeint NULL COMMENT "Contra account currency FK — maps to CONTRA_ACCT_CRNCY_ID",
  `exchange_rate` decimal(38,12) NULL COMMENT "Source system exchange rate — maps to EXCH_RATE (informational; pipeline uses                  
  fact_exchange_rates for mid-rate)",
  `value_date` date NULL COMMENT "Value date — maps to VALUE_DT",
  `create_date` date NULL COMMENT "Row creation date — maps to CREATE_DT",
  `event_id` largeint NULL COMMENT "FK → dim_event — maps to EVENT_ID",
  `tran_journal_id` largeint NULL COMMENT "Transaction journal ID — maps to TRAN_JOURNAL_ID",
  `event_journal_id` largeint NULL COMMENT "Event journal ID — maps to EVENT_JOURNAL_ID",
  `event_charge_journal_id` largeint NULL COMMENT "Charge journal ID — maps to EVENT_CHRG_JOURNAL_ID",
  `event_tax_journal_id` largeint NULL COMMENT "Tax journal ID — maps to EVENT_TAX_JOURNAL_ID",
  `origin_branch_id` largeint NULL COMMENT "FK → dim_business_unit — maps to ORIGIN_BU_ID",
  `contra_branch_id` largeint NULL COMMENT "Contra branch FK — maps to CONTRA_BU_ID",
  `channel_id` largeint NULL COMMENT "FK → dim_channel — maps to CHANNEL_ID",
  `contra_account_number` varchar(60) NULL COMMENT "maps to CONTRA_ACCT_NO",
  `contra_account_type_id` largeint NULL COMMENT "maps to CONTRA_ACCT_TY_ID",
  `contra_account_amount` decimal(38,10) NULL COMMENT "maps to CONTRA_ACCT_AMT",
  `total_charge_amount` decimal(38,10) NULL COMMENT "maps to TOTAL_CHRG_AMT",
  `total_tax_amount` decimal(38,10) NULL COMMENT "maps to TOTAL_TAX_AMT",
  `event_cost` decimal(38,10) NULL COMMENT "maps to EVENT_COST",
  `total_cost` decimal(38,10) NULL COMMENT "maps to TOTAL_COST",
  `transaction_reference` varchar(100) NULL COMMENT "maps to TRAN_REF_TXT. Historic rows have NULL (VAT/charge entries).",
  `cheque_number` largeint NULL COMMENT "maps to CHQ_NO",
  `transaction_description` varchar(300) NULL COMMENT "maps to TRAN_DESC",
  `supervisor_id` largeint NULL COMMENT "maps to SUPERVISOR_ID",
  `originator_id` largeint NULL COMMENT "maps to ORIGINATOR_ID",
  `user_id` varchar(24) NULL COMMENT "maps to USER_ID",
  `created_by` varchar(24) NULL COMMENT "maps to CREATED_BY",
  `record_status` char(1) NULL COMMENT "maps to REC_ST",
  `version_number` largeint NULL COMMENT "maps to VERSION_NO",
  `balance_update_status` char(1) NULL COMMENT "maps to BAL_UPDATE_ST",
  `bank_recon_flag` char(1) NULL DEFAULT "N" COMMENT "maps to BANK_RECON_FG",
  `bank_recon_id` largeint NULL COMMENT "maps to BANK_RECON_ID",
  `row_timestamp` datetime NULL COMMENT "Source row timestamp — maps to ROW_TS",
  `source_create_timestamp` datetime NULL COMMENT "Source system create timestamp — maps to SYS_CREATE_TS",
  `etl_load_date` datetime NULL COMMENT "ETL pipeline load timestamp — populated by Airflow DAG"
) ENGINE=OLAP
UNIQUE KEY(`transaction_history_id`, `transaction_date`, `gl_account_id`)
COMMENT 'GL transaction fact table — source: STAGING.GL_ACCOUNT_HISTORY. One row per journal entry. Primary source for mart_bs_transactions and                    
