CREATE TABLE IF NOT EXISTS `fact_gl_transactions_1` (
  `transaction_date` date NULL COMMENT "System post date (from TRAN_DT)",
  `value_date` date NULL COMMENT "Effective date for accounting/interest (from VALUE_DT)",
  `gl_account_id` largeint NULL COMMENT "Refers to dim_general_ledger (from GL_ACCT_ID)",
  `transaction_journal_id` largeint NULL COMMENT "Unique batch ID for double-entry matching (from TRAN_JOURNAL_ID)",
  `transaction_history_id` largeint NULL COMMENT "Primary unique key for this entry (from ACCT_HIST_ID)",
  `gl_account_number` varchar(64) NULL COMMENT "Human-readable GL code (from GL_ACCT_NO)",
  `debit_credit_indicator` varchar(5) NULL COMMENT "D for Debit, C for Credit (from DR_CR_IND)",
  `transaction_description` varchar(500) NULL COMMENT "Narrative text for the entry (from TRAN_DESC)",
  `transaction_reference_text` varchar(100) NULL COMMENT "External reference/slip info (from TRAN_REF_TXT)",
  `cheque_number` bigint NULL COMMENT "Physical check reference (from CHQ_NO)",
  `contra_account_number` varchar(64) NULL COMMENT "Account number of the offsetting entry (from CONTRA_ACCT_NO)",
  `contra_branch_id` int NULL COMMENT "Branch where the offsetting entry lives (from CONTRA_BU_ID)",
  `contra_currency_id` int NULL COMMENT "Currency of the offsetting account (from CONTRA_ACCT_CRNCY_ID)",
  `contra_account_type_id` int NULL COMMENT "Type of account on the offsetting side (from CONTRA_ACCT_TY_ID)",
  `origin_branch_id` int NULL COMMENT "Branch where the entry was initiated (from ORIGIN_BU_ID)",
  `original_currency_key` int NULL COMMENT "Currency of the counter transaction (from TXN_CRNCY_ID)",
  `account_currency_id` int NULL COMMENT "Refers to dim_currency (from ACCT_CRNCY_ID)",
  `maker_user_id` int NULL COMMENT "Staff who initiated, refers to dim_user (from ORIGINATOR_ID)",
  `checker_user_key` int NULL COMMENT "Staff who approved, refers to dim_user (from SUPERVISOR_ID)",
  `channel_id` int NULL COMMENT "Origin: ATM, Mobile, Teller, etc. (from CHANNEL_ID)",
  `transaction_event_type_id` int NULL COMMENT "Type of event: Withdrawal, Transfer, etc. (from EVENT_ID)",
  `event_batch_id` largeint NULL COMMENT "Main batch ID grouping all related entries (from EVENT_JOURNAL_ID)",
  `event_charge_batch_id` largeint NULL COMMENT "Link to charges related to this event (from EVENT_CHRG_JOURNAL_ID)",
  `event_tax_batch_id` largeint NULL COMMENT "Link to tax entries for this transaction (from EVENT_TAX_JOURNAL_ID)",
  `bank_reconciliation_id` largeint NULL COMMENT "ID of the reconciliation batch (from BANK_RECON_ID)",
  `original_transaction_amount` decimal(18,2) NULL COMMENT "Amount in the currency used at the counter (from TXN_AMT)",
  `account_currency_amount` decimal(18,2) NULL COMMENT "Amount in the GL accounts local currency (from ACCT_AMT)",
  `contra_account_amount` decimal(18,2) NULL COMMENT "Amount on the other side of the entry (from CONTRA_ACCT_AMT)",
  `exchange_rate_applied` decimal(18,8) NULL COMMENT "Rate used if currencies were different (from EXCH_RATE)",
  `running_statement_balance` decimal(18,2) NULL COMMENT "Account balance after this transaction (from STMNT_BAL)",
  `total_tax_amount` decimal(18,2) NULL COMMENT "Sum of all taxes for this transaction (from TOTAL_TAX_AMT)",
  `total_charges_amount` decimal(18,2) NULL COMMENT "Sum of all fees for this transaction (from TOTAL_CHRG_AMT)",
  `total_transaction_cost` decimal(18,2) NULL COMMENT "Operational cost to the bank (from TOTAL_COST)",
  `specific_event_cost` decimal(18,2) NULL COMMENT "Direct cost associated with this event (from EVENT_COST)",
  `is_reconciled_flag` varchar(10) NULL COMMENT "Reconciled with bank statement (from BANK_RECON_FG, string in source)",
  `record_status` varchar(20) NULL COMMENT "Active, Deleted, Reversed, etc. (from REC_ST)",
  INDEX idx_txn_ref (`transaction_reference_text`) USING INVERTED,
  INDEX idx_dr_cr (`debit_credit_indicator`) USING INVERTED
) ENGINE=OLAP
DUPLICATE KEY(`transaction_date`, `value_date`, `gl_account_id`)
