CREATE TABLE IF NOT EXISTS `fact_ib_transactions` (
  `ib_txn_id` largeint NOT NULL COMMENT "Source system ID (client_transactions.ID)",
  `txn_date` datetime NOT NULL COMMENT "Transaction date and time (partition key)",
  `txn_reference` varchar(100) NULL COMMENT "Unique IB-generated transaction reference (TXN_ID)",
  `cbs_receipt` varchar(100) NULL COMMENT "Core banking system receipt/journal reference",
  `initiated_by` varchar(100) NULL COMMENT "Username of the client who initiated the transaction",
  `branch_id` varchar(10) NULL COMMENT "Branch where the transaction was initiated",
  `partner_code` varchar(40) NULL COMMENT "Link to dim_ib_client_profile via partner_code",
  `debit_account` varchar(40) NULL COMMENT "Source account number (DEBIT_ACCT)",
  `debit_account_name` varchar(100) NULL,
  `credit_account` varchar(40) NULL COMMENT "Destination account number (CREDIT_ACCT)",
  `credit_account_name` varchar(100) NULL,
  `credit_msisdn` varchar(200) NULL COMMENT "Destination mobile number for mobile money transfers",
