  `charge` decimal(18,2) NULL COMMENT "Service charge applied",
  `currency` varchar(10) NULL,
  `event_code` varchar(200) NULL COMMENT "IB event/transaction type code",
  `transfer_mode` varchar(20) NULL COMMENT "e.g., INTRA, INTER, SWIFT, RTGS, PESALINK",
  `narrations` varchar(600) NULL COMMENT "Transaction narrative/description",
  `cbs_status` varchar(10) NULL COMMENT "Core banking processing status (SUCCESS, FAILED, PENDING)",
