  `third_party_reference` varchar(255) NULL COMMENT "Third-party/switch reference number",
  `third_party_value` varchar(255) NULL COMMENT "Third-party value returned (e.g., utility token)",
  `comments` varchar(1000) NULL,
  `rec_status` varchar(20) NULL COMMENT "Record status",
