  `secondary_officer_id` largeint NULL,
  `accrued_interest_subsidy` decimal(38,10) NULL,
  `last_interest_subsidy_amount` decimal(38,10) NULL,
  `subsidy_interest_rate` decimal(38,10) NULL,
  `interest_subsidy_arrear` decimal(38,10) NULL
) ENGINE=OLAP
