CREATE TABLE IF NOT EXISTS `fact_loan_account_summary` (
  `account_id` bigint NOT NULL COMMENT "Unique internal ID for the loan account (PK)",
  `account_number` varchar(60) NOT NULL COMMENT "Customer-facing loan account number",
  `last_customer_activity_date` date NOT NULL COMMENT "Date of last customer activity — partition key",
  `product_id` bigint NULL,
  `repayment_account` bigint NULL COMMENT "Linked repayment account ID",
  `ledger_balance` decimal(38,10) NULL,
  `cleared_balance` decimal(38,10) NULL,
  `uncleared_balance` decimal(38,10) NULL,
  `uncleared_balance_2` decimal(38,10) NULL,
  `pending_credit_balance` decimal(38,10) NULL COMMENT "Pending credits not yet cleared",
  `pending_debit_balance` decimal(38,10) NULL COMMENT "Pending debits not yet cleared",
  `undisbursed_balance` decimal(38,10) NULL,
  `amortised_balance` decimal(38,10) NULL,
  `contingent_balance` decimal(38,10) NULL COMMENT "Contingent/off-balance-sheet exposure",
  `unapplied_funds` decimal(38,10) NULL COMMENT "Funds received but not yet applied to the loan",
  `past_due_balance` decimal(38,10) NULL COMMENT "Total overdue balance",
  `debit_balance_forward` decimal(38,10) NULL,
  `ledger_balance_forward` decimal(38,10) NULL,
  `cleared_balance_forward` decimal(38,10) NULL,
  `total_disbursement` decimal(38,10) NULL COMMENT "Total amount disbursed to date",
  `last_disbursement_amount` decimal(38,10) NULL,
  `last_disbursement_date` date NULL COMMENT "Date of the last disbursement",
  `first_disbursement_amount` decimal(38,10) NULL COMMENT "Amount of the first disbursement",
  `first_disbursement_date` date NULL COMMENT "Date of the first disbursement",
  `last_payment_amount` decimal(38,10) NULL,
  `last_payment_date` date NULL COMMENT "Date of the last payment received",
  `first_payment_amount` decimal(38,10) NULL COMMENT "Amount of the first payment received",
  `first_payment_date` date NULL COMMENT "Date of the first payment",
  `next_payment_amount` decimal(38,10) NULL COMMENT "Amount of the next scheduled payment",
  `next_payment_date` date NULL COMMENT "Date of the next scheduled payment",
  `current_payoff_amount` decimal(38,10) NULL COMMENT "Total amount required to close the loan today",
  `total_payment_due` decimal(38,10) NULL COMMENT "Total payment currently due",
  `today_payable_amount` decimal(38,10) NULL COMMENT "Amount payable as of today",
  `ytd_payment_count` bigint NULL COMMENT "Year-to-date count of payments made",
  `ltd_payment_count` bigint NULL COMMENT "Life-to-date count of payments made",
  `debit_turnover` decimal(38,10) NULL,
  `credit_turnover` decimal(38,10) NULL,
  `debit_count` bigint NULL,
  `credit_count` bigint NULL,
  `ytd_returns_count` bigint NULL,
  `ytd_clearing_returns_count` bigint NULL,
  `debit_interest_accrued` decimal(38,10) NULL,
  `debit_interest_per_day` decimal(38,10) NULL,
  `debit_interest_accrued_ptd` decimal(38,10) NULL,
  `debit_interest_accrued_ytd` decimal(38,10) NULL COMMENT "Debit interest accrued year-to-date",
  `debit_interest_accrued_ltd` decimal(38,10) NULL COMMENT "Debit interest accrued life-to-date",
  `debit_interest_accrued_fy` decimal(38,10) NULL COMMENT "Debit interest accrued for the financial year",
  `debit_interest_remainder_accrued` decimal(38,10) NULL COMMENT "Fractional remainder debit interest accrued",
  `debit_interest_remainder_per_day` decimal(38,10) NULL COMMENT "Fractional remainder daily debit interest",
  `debit_interest_suspended` decimal(38,10) NULL COMMENT "Debit interest suspended (non-performing)",
  `suspended_interest_paid_amount` decimal(38,10) NULL COMMENT "Suspended interest that has been recovered",
  `capitalized_interest_amount` decimal(38,10) NULL,
  `suspended_capitalized_late_fee` decimal(38,10) NULL COMMENT "Capitalized late fee that has been suspended",
  `prepaid_interest_amount` decimal(38,10) NULL COMMENT "Interest paid in advance",
  `interest_past_due_amount` decimal(38,10) NULL COMMENT "Interest that is overdue",
  `accrued_interest_subsidy` decimal(38,10) NULL COMMENT "Accrued interest subsidy amount",
  `accrued_interest_subsidy_ltd` decimal(38,10) NULL COMMENT "Life-to-date accrued interest subsidy",
  `last_interest_subsidy_amount` decimal(38,10) NULL COMMENT "Last interest subsidy amount received",
  `subsidy_interest_rate` decimal(38,10) NULL COMMENT "Interest rate applied to the subsidy",
  `current_debit_interest_rate` decimal(38,12) NULL COMMENT "Current applicable debit interest rate",
  `calculated_effective_rate` decimal(38,12) NULL COMMENT "Calculated effective interest rate",
  `charges_applied` decimal(38,10) NULL COMMENT "Total charges applied to the account",
  `debit_interest_charged` decimal(38,10) NULL COMMENT "Debit interest charged in the period",
  `total_cost` decimal(38,10) NULL COMMENT "Total cost of the account for the period",
  `total_charges` decimal(38,10) NULL COMMENT "Total charges levied",
  `total_tax` decimal(38,10) NULL COMMENT "Total tax applied",
  `charges_due` decimal(38,10) NULL,
  `prepaid_charge_balance` decimal(38,10) NULL,
  `loan_fees_due_accrued` decimal(38,10) NULL COMMENT "Loan fees accrued and due",
  `prepaid_insurance_balance` decimal(38,10) NULL,
  `insurance_accrued` decimal(38,10) NULL,
  `provision_balance` decimal(38,10) NULL COMMENT "Current provision balance",
  `cumulative_provision_balance` decimal(38,10) NULL COMMENT "Cumulative provision held life-to-date",
  `previous_provision_balance` decimal(38,10) NULL COMMENT "Provision balance from the prior period",
  `restructure_count` bigint NULL COMMENT "Number of times this loan has been restructured",
  `restructured_principal_balance` decimal(38,10) NULL COMMENT "Principal balance after restructuring",
  `last_restructure_date` date NULL COMMENT "Date of the most recent restructure",
  `statement_opening_balance` decimal(38,10) NULL COMMENT "Opening balance on the latest statement",
  `statement_count` bigint NULL COMMENT "Number of statements generated",
  `statement_start_date` date NULL COMMENT "Start date of the current statement period",
  `next_statement_date` date NULL COMMENT "Scheduled date for next statement generation",
  `last_accrual_date` date NULL COMMENT "Last date interest was accrued",
  `next_accrual_date` date NULL COMMENT "Next scheduled interest accrual date",
  `last_accrual_time` datetime NULL COMMENT "Timestamp of the last accrual run",
  `current_accrual_date` date NULL COMMENT "Current accrual calculation date",
  `next_rate_change_date` date NULL COMMENT "Date of the next scheduled interest rate change",
  `last_rate_change_date` date NULL COMMENT "Date of the most recent interest rate change",
  `next_disbursement_date` date NULL COMMENT "Scheduled date for the next disbursement",
  `next_capitalization_date` date NULL COMMENT "Scheduled date for the next interest capitalization",
  `next_late_fee_capitalize_date` date NULL COMMENT "Scheduled date for next late fee capitalization",
  `delinquent_date` date NULL COMMENT "Date the account became delinquent",
  `last_late_fee_date` date NULL COMMENT "Date the last late fee was applied",
  `last_update_due_date` date NULL,
  `last_product_update_date` date NULL COMMENT "Date the product was last changed on account",
  `last_reversal_date` date NULL COMMENT "Date of the last transaction reversal",
  `last_backdated_txn_date` date NULL COMMENT "Date of the last backdated transaction",
  `earliest_backvalue_date` date NULL COMMENT "Earliest back-value date allowed",
  `last_backvalue_date` date NULL COMMENT "Date of the last back-value transaction",
  `last_provision_date` date NULL COMMENT "Date the last provision entry was made",
  `next_risk_upgrade_date` date NULL COMMENT "Scheduled date for next risk grade upgrade",
  `record_status` char(1) NULL,
  `statistics_update_flag` char(1) NULL COMMENT "Y/N flag indicating stats need refresh",
  `temp_reclassification_status` char(1) NULL COMMENT "Temporary reclassification status flag",
  `accrual_due_flag` char(1) NULL,
  `debit_interest_override_flag` char(1) NULL COMMENT "Y/N override flag for debit interest rate",
  `balance_change_flag` char(1) NULL COMMENT "Flag indicating balance changed in this cycle",
  `is_restructured_loan` char(1) NULL COMMENT "Y if this loan has been restructured",
  `late_fee_status` varchar(10) NULL COMMENT "Current status of late fee processing",
  `created_date` date NULL,
  `user_id` bigint NULL,
  `created_by` varchar(24) NULL,
  `etl_load_date` date NULL COMMENT "Date this record was loaded into Doris",
  `etl_batch_id` varchar(64) NULL COMMENT "ETL batch/job ID for lineage tracking"
) ENGINE=OLAP
UNIQUE KEY(`account_id`, `account_number`, `last_customer_activity_date`)
COMMENT 'Periodic snapshot fact table of loan account balances, accruals, payments and provisioning. Source: STAGING.LOAN_ACCOUNT_SUMMARY (Oracle CBS).'
PARTITION BY RANGE(`last_customer_activity_date`)
(PARTITION p_history VALUES [('0000-01-01'), ('2024-01-01')),
PARTITION p_2024 VALUES [('2024-01-01'), ('2025-01-01')),
PARTITION p_2025 VALUES [('2025-01-01'), ('2026-01-01')),
PARTITION p_2026 VALUES [('2026-01-01'), ('2027-01-01')),
PARTITION p_future VALUES [('2027-01-01'), (MAXVALUE)))
DISTRIBUTED BY HASH(`account_id`) BUCKETS 32
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"bloom_filter_columns" = "account_number, record_status, delinquent_date, product_id, current_accrual_date, balance_change_flag, etl_load_date, accrual_due_flag",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"store_row_column" = "true",
"row_store_page_size" = "16384",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
CREATE TABLE IF NOT EXISTS `fact_loan_application_metric_map` (
  `application_id` largeint NOT NULL COMMENT "PK from fact_credit_applications",
  `application_date` date NOT NULL COMMENT "Submission date (partition key in source)",
  `application_year` smallint NULL COMMENT "Year of application",
  `application_quarter` varchar(10) NULL COMMENT "e.g. 2025-Q3",
  `application_year_month` varchar(10) NULL COMMENT "e.g. 2025-09",
  `application_month_name` varchar(20) NULL COMMENT "e.g. September",
  `application_fiscal_year` smallint NULL COMMENT "TCB fiscal year (Jul-Jun)",
  `application_fiscal_quarter` smallint NULL COMMENT "TCB fiscal quarter",
  `application_is_business_day` smallint NULL COMMENT "1 if business day",
  `customer_id` largeint NULL,
  `customer_number` varchar(64) NULL,
  `customer_full_name` varchar(255) NULL,
  `customer_category` varchar(100) NULL,
  `customer_segment_id` int NULL,
  `customer_gender` varchar(10) NULL,
  `customer_is_resident_flag` tinyint NULL,
  `customer_kyc_level` int NULL,
  `customer_industry_sector` varchar(255) NULL COMMENT "Joined via dim_customer.industry_sector_id",
  `branch_id` largeint NULL,
  `branch_number` varchar(64) NULL,
  `branch_name` varchar(255) NULL,
  `branch_type` varchar(100) NULL,
  `urban_rural_classification` varchar(50) NULL,
  `district_id` int NULL,
  `product_id` varchar(64) NULL,
  `product_code` varchar(30) NULL,
  `product_name` varchar(255) NULL,
  `product_category` varchar(100) NULL,
  `product_type` varchar(100) NULL,
  `effective_currency_id` largeint NULL,
  `currency_iso_code` varchar(10) NULL,
  `currency_category` varchar(50) NULL COMMENT "Local vs Foreign",
  `is_multi_currency_flag` tinyint NULL,
  `primary_officer_id` int NULL,
  `primary_officer_name` varchar(300) NULL,
  `primary_officer_branch_id` int NULL,
  `approving_manager_id` int NULL,
  `approving_manager_name` varchar(300) NULL,
  `credit_type_id` int NULL COMMENT "FILTER: Term Loan / Overdraft / etc. - dim TBD",
  `credit_portfolio_id` int NULL COMMENT "Retail / SME - dim TBD",
  `risk_class_id` int NULL COMMENT "Risk class at request - dim TBD",
  `rejection_reason_id` int NULL COMMENT "Populated on declines only - dim TBD",
  `application_reason_id` int NULL COMMENT "Reason for credit request - dim TBD",
  `industry_id` int NULL COMMENT "App-level industry exposure - dim TBD",
  `application_status` varchar(20) NULL COMMENT "FILTER: PENDING/APPROVED/DECLINED/DISBURSED",
  `record_status` varchar(20) NULL COMMENT "FILTER: Active/Deleted",
  `application_outcome` varchar(40) NULL COMMENT "PENDING / APPROVED_NOT_DISBURSED / DISBURSED / DECLINED / EXPIRED",
  `requested_limit_amount` decimal(18,2) NULL,
  `approved_limit_amount` decimal(18,2) NULL,
  `approval_variance_amount` decimal(18,2) NULL COMMENT "approved - requested",
  `approval_variance_pct` decimal(10,4) NULL COMMENT "(approved-requested)/requested",
  `min_contribution_ratio` decimal(10,4) NULL,
  `requested_term_duration` int NULL,
  `requested_term_unit` varchar(20) NULL,
  `approved_term_duration` int NULL,
  `approved_term_unit` varchar(20) NULL,
  `requested_term_months` int NULL COMMENT "Normalized to months",
  `approved_term_months` int NULL COMMENT "Normalized to months",
  `term_variance_months` int NULL,
  `loan_cycle_count` int NULL,
  `loan_cycle_bucket` varchar(20) NULL COMMENT "New (1) / Repeat (2-3) / Loyal (4+)",
  `approval_date` date NULL,
  `decline_date` date NULL,
  `approved_disbursement_date` date NULL,
  `validity_expiration_date` date NULL,
  `tat_approval_days` int NULL COMMENT "approval_date - application_date",
  `tat_decline_days` int NULL COMMENT "decline_date - application_date",
  `tat_disbursement_days` int NULL COMMENT "approved_disbursement_date - approval_date",
  `tat_total_days` int NULL COMMENT "End-to-end (disbursement - application)",
  `is_policy_exception` tinyint NULL,
  `is_multi_beneficiary` tinyint NULL,
  `is_refinance_flag` tinyint NULL COMMENT "1 if refinanced_loan_id IS NOT NULL",
  `application_reference_no` varchar(100) NULL,
  `last_refreshed_ts` datetime NULL COMMENT "Set by refresh job"
) ENGINE=OLAP
DUPLICATE KEY(`application_id`, `application_date`)
DISTRIBUTED BY HASH(`application_id`) BUCKETS 8
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"compression" = "ZSTD",
"light_schema_change" = "true",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728"
);
CREATE TABLE IF NOT EXISTS `fact_loan_portfolio_metrics` (
  `transaction_date` date NOT NULL,
  `gl_account_id` largeint NULL,
  `transaction_journal_id` largeint NULL,
  `branch_id` int NULL,
  `branch_name` varchar(200) NULL,
  `ledger_number` int NULL,
  `gl_account_name` varchar(300) NULL,
  `gl_account_number` varchar(100) NULL,
  `loan_product` varchar(200) NULL,
  `product_id` int NULL,
  `loan_category` varchar(100) NULL,
  `metric_label` varchar(200) NULL,
  `metric_name` varchar(100) NOT NULL,
  `debit_credit_indicator` varchar(10) NULL,
  `transaction_description` varchar(500) NULL,
  `transaction_event_type_id` largeint NULL,
  `event_description` varchar(300) NULL,
  `currency_code` varchar(50) NULL,
  `account_currency_amount` decimal(20,4) NULL,
  `signed_amount` decimal(20,4) NULL,
  `running_statement_balance` decimal(20,4) NULL,
  `total_tax_amount` decimal(20,4) NULL,
  `total_charges_amount` decimal(20,4) NULL,
  `etl_loaded_at` datetime NULL,
  `delinquency_stage` int NULL,
  `delinquency_stage_label` varchar(100) NULL
) ENGINE=OLAP
DUPLICATE KEY(`transaction_date`, `gl_account_id`, `transaction_journal_id`)
DISTRIBUTED BY HASH(`ledger_number`) BUCKETS 10
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
