CREATE TABLE IF NOT EXISTS `fact_loan_recoveries` (
  `recovery_date` date NOT NULL COMMENT "The date the payment was received",
  `loan_account_number` largeint NOT NULL COMMENT "The primary loan identifier for joining",
  `branch_name` varchar(100) NULL COMMENT "Branch credited with the recovery income",
  `account_name` varchar(255) NULL COMMENT "Full name of the customer",
  `product_name` varchar(100) NULL COMMENT "The loan product type (e.g., Personal Loan)",
  `amount_recovered` decimal(18,2) NULL COMMENT "The actual cash amount collected",
  `principal_balance` decimal(18,2) NULL COMMENT "Principal debt left after this specific recovery",
  `current_payoff_amount` decimal(18,2) NULL COMMENT "Total debt (Principal + Int) remaining to close",
  INDEX idx_recov_date (`recovery_date`) USING INVERTED,
  INDEX idx_recov_branch (`branch_name`) USING INVERTED
) ENGINE=OLAP
DUPLICATE KEY(`recovery_date`, `loan_account_number`)
PARTITION BY RANGE(`recovery_date`)
