CREATE TABLE IF NOT EXISTS `fact_loan_repayment_enriched` (
  `schedule_event_id` largeint NOT NULL COMMENT "PK from fact_loan_repayment_schedule",
  `loan_account_id` largeint NOT NULL COMMENT "FK to dim_account",
  `installment_due_date` date NOT NULL COMMENT "Payment due date (partition key)",
  `account_number` varchar(64) NULL COMMENT "Public account number",
  `account_name` varchar(255) NULL COMMENT "Account name/title",
  `product_category` varchar(50) NULL COMMENT "Product category from dim_account",
  `product_sub_category` varchar(50) NULL COMMENT "Product sub-category from dim_account",
  `account_status_code` varchar(20) NULL COMMENT "Raw status code on the account",
  `account_status_description` varchar(100) NULL COMMENT "Human-readable account status",
  `customer_id` largeint NULL COMMENT "FK to dim_customer",
  `customer_number` varchar(64) NULL COMMENT "Business customer number",
  `customer_full_name` varchar(255) NULL COMMENT "Customer full name",
  `customer_category` varchar(100) NULL COMMENT "Customer category",
  `gender` varchar(10) NULL COMMENT "Customer gender",
  `customer_segment_id` int NULL COMMENT "Customer segment key",
  `branch_id` int NULL COMMENT "Branch ID",
  `branch_name` varchar(255) NULL COMMENT "Branch name",
  `business_unit_type_description` varchar(100) NULL COMMENT "HO, Retail Branch, etc.",
  `urban_rural_classification` varchar(50) NULL COMMENT "Rural vs Urban",
  `currency_iso_code` varchar(10) NULL COMMENT "ISO currency code",
  `product_id` varchar(64) NULL COMMENT "Product ID from dim_account",
  `product_code` varchar(30) NULL COMMENT "Product code from dim_product",
  `product_name_description` varchar(255) NULL COMMENT "Product name from dim_product",
  `product_type` varchar(100) NULL COMMENT "Product type from dim_product",
  `product_group` varchar(50) NULL COMMENT "Business | Personal | MIC from mapping_loan_products",
  `installment_type` varchar(50) NULL COMMENT "PRINCIPAL, INTEREST, FEE, INSURANCE",
  `installment_description` varchar(255) NULL COMMENT "Human-readable payment type",
  `funding_source_type` varchar(50) NULL COMMENT "Internal vs External",
  `installment_status_code` varchar(20) NULL COMMENT "Raw status code on the installment",
  `installment_status_description` varchar(100) NULL COMMENT "Human-readable installment status",
  `scheduled_installment_amount` decimal(18,2) NULL COMMENT "Total amount due this period",
  `actual_amount_paid` decimal(18,2) NULL COMMENT "Amount paid against this installment",
  `remaining_unpaid_balance` decimal(18,2) NULL COMMENT "Outstanding / arrears amount",
  `original_scheduled_amount` decimal(18,2) NULL COMMENT "Amount at loan inception",
  `amount_decrease_adjustment` decimal(18,2) NULL COMMENT "Adjustments / waivers applied",
  `service_date` date NULL COMMENT "Actual processing date",
  `next_compounding_date` date NULL COMMENT "Next interest calculation date",
  `is_interest_component` tinyint NULL COMMENT "1 = interest row",
  `is_capitalized_flag` tinyint NULL COMMENT "1 = unpaid interest capitalised",
  `is_late_fee_applicable` tinyint NULL COMMENT "1 = penalty can be triggered",
  `is_suspended_flag` tinyint NULL COMMENT "1 = row on hold",
  `is_arrears_eligible` tinyint NULL COMMENT "1 = installment status not Cancelled; eligible for arrears reporting",
  `is_past_due` tinyint NULL COMMENT "1 = due date < today AND remaining_unpaid_balance > 0 AND arrears eligible",
  `days_past_due` int NULL COMMENT "Calendar days overdue; 0 for current or fully paid rows",
  `delinquency_bucket` varchar(20) NULL COMMENT "Current | 1-30 DPD | 31-60 DPD | 61-90 DPD | 90+ DPD | N/A",
  `arrears_amount` decimal(18,2) NULL COMMENT "remaining_unpaid_balance for eligible past-due rows; else 0",
  `is_paid_on_time` tinyint NULL COMMENT "1 = fully paid on or before due date at full scheduled amount",
  `is_paid_late` tinyint NULL COMMENT "1 = paid after due date",
  `days_paid_late` int NULL COMMENT "Days between due date and service_date for late-paid rows; else 0",
  `payment_status_label` varchar(30) NULL COMMENT "Paid On Time | Paid Late | Overdue | Current | Cancelled | Non-Accrual | Other",
  `performing_type` varchar(20) NULL COMMENT "Performing | NPL from mapping_loan_classification_rules",
  `classification` varchar(30) NULL COMMENT "Current | Special Mention | Substandard | Doubtful | Loss",
  `provisioning_pct` decimal(5,2) NULL COMMENT "Provisioning rate % from mapping_loan_classification_rules (0, 1, 20, 50, 100)",
  `provisioning_amount` decimal(18,2) NULL COMMENT "arrears_amount * provisioning_pct / 100 — estimated provision in TZS",
  `is_npl` tinyint NULL COMMENT "1 = performing_type = NPL",
  `dw_refresh_ts` datetime NULL COMMENT "Timestamp of last DW load",
  INDEX idx_enriched_inst_status (`installment_status_code`) USING INVERTED,
  INDEX idx_enriched_acct_status (`account_status_code`) USING INVERTED,
  INDEX idx_enriched_inst_type (`installment_type`) USING INVERTED,
  INDEX idx_enriched_bucket (`delinquency_bucket`) USING INVERTED,
  INDEX idx_enriched_past_due (`is_past_due`) USING INVERTED,
  INDEX idx_enriched_npl (`is_npl`) USING INVERTED,
  INDEX idx_enriched_class (`classification`) USING INVERTED,
  INDEX idx_enriched_performing (`performing_type`) USING INVERTED,
  INDEX idx_enriched_prod_group (`product_group`) USING INVERTED,
  INDEX idx_enriched_pay_label (`payment_status_label`) USING INVERTED,
  INDEX idx_enriched_branch (`branch_name`) USING INVERTED,
  INDEX idx_enriched_prod_cat (`product_category`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`schedule_event_id`, `loan_account_id`, `installment_due_date`)
PARTITION BY RANGE(`installment_due_date`)
