CREATE TABLE IF NOT EXISTS `fact_loan_repayment_schedule` (
  `schedule_event_id` largeint NOT NULL COMMENT "Unique id for each installment row",
  `loan_account_id` largeint NOT NULL COMMENT "Refers to dim_account",
  `installment_due_date` date NOT NULL COMMENT "The date the payment is expected",
  `installment_type` varchar(50) NULL COMMENT "e.g., 'PRINCIPAL', 'INTEREST', 'FEE', 'INSURANCE'",
  `installment_description` varchar(255) NULL COMMENT "Human-readable name of the payment type",
  `funding_source_type` varchar(50) NULL COMMENT "Internal vs. External funding source",
  `record_status` varchar(20) NULL COMMENT "Active, Paid, Cancelled, or Rescheduled",
  `scheduled_installment_amount` decimal(18,2) NULL COMMENT "The total payment amount due for this period",
  `actual_amount_paid` decimal(18,2) NULL COMMENT "How much has been paid against this specific installment",
  `remaining_unpaid_balance` decimal(18,2) NULL COMMENT "The \"Arrears\" or outstanding amount for this row",
  `original_scheduled_amount` decimal(18,2) NULL COMMENT "The amount originally calculated at loan inception",
  `compounding_balance_base` decimal(18,2) NULL COMMENT "The balance used to calculate compound interest",
  `amount_decrease_adjustment` decimal(18,2) NULL COMMENT "Track adjustments/waivers applied to this row",
  `is_interest_component` tinyint NULL COMMENT "1 if this row represents interest",
  `is_capitalized_flag` tinyint NULL COMMENT "1 if unpaid interest is added to the principal",
  `is_late_fee_applicable` tinyint NULL COMMENT "1 if this installment can trigger penalties",
  `is_suspended_flag` tinyint NULL COMMENT "1 if this specific row is on hold",
  `repayment_source_account_id` largeint NULL COMMENT "The account to be auto-debited for this payment",
  `charge_type_id` int NULL COMMENT "Link to fee configuration (Dim_Charge)",
  `loan_insurance_reference` int NULL COMMENT "Link to specific insurance policy details",
  `payment_instruction_id` int NULL COMMENT "Link to standing instruction/DD details",
  `related_charge_journal_id` largeint NULL COMMENT "Link to automated fee entries",
  `holiday_processing_logic` int NULL COMMENT "Logic used if Due Date falls on a holiday",
  `skip_payment_logic` int NULL COMMENT "Rule used if the customer misses a payment",
  `pricing_tier_level` int NULL COMMENT "Useful if the loan has stepped interest rates",
  `next_compounding_date` date NULL COMMENT "When the next interest calculation occurs",
  `service_date` date NULL COMMENT "Actual date of processing for this row",
  `system_creation_date` date NULL COMMENT "Use DUE_DT for business analysis",
  `system_created_by` varchar(50) NULL COMMENT "Technical audit field",
  `user_id` varchar(50) NULL COMMENT "Technical audit field",
  INDEX idx_sch_status (`record_status`) USING INVERTED,
  INDEX idx_sch_due_dt (`installment_due_date`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`schedule_event_id`, `loan_account_id`, `installment_due_date`)
PARTITION BY RANGE(`installment_due_date`)
