CREATE TABLE IF NOT EXISTS `fact_loan_transactions` (
  `transaction_date` date NOT NULL COMMENT "Official
  posting date",
  `loan_account_id` largeint NULL COMMENT "Link to
  dim_account",
  `loan_transaction_id` largeint NULL COMMENT "Primary unique
   key for the loan entry",
  `value_date` date NULL COMMENT "Date for interest        
  calculation",
  `origin_branch_id` int NULL COMMENT "Branch where txn was
  initiated",
  `maker_user_id` int NULL COMMENT "Staff who captured the
  transaction",
  `checker_user_id` int NULL COMMENT "Staff who authorized 
  the transaction",
  `channel_id` int NULL COMMENT "Link to dim_channel",
  `event_type_id` int NULL COMMENT "Transaction event type",
  `transaction_currency_id` int NULL COMMENT "Currency of the
   transaction",
  `tax_reference_id` int NULL COMMENT "Link to tax           
  configuration",
  `charge_reference_id` int NULL COMMENT "Link to charge
  configuration",
  `memo_type_code` int NULL COMMENT "Internal accounting memo
   classification",
  `principal_amount` decimal(18,2) NULL COMMENT "Principal
  component of the transaction",
  `interest_amount` decimal(18,2) NULL COMMENT "Interest   
  component",
  `insurance_amount` decimal(18,2) NULL COMMENT "Insurance
  component",
  `original_txn_amount` decimal(18,2) NULL COMMENT "Original
  transaction amount",
  `account_currency_amount` decimal(18,2) NULL COMMENT "Amount in account currency",
  `principal_remaining_bal` decimal(18,2) NULL COMMENT "Remaining principal balance",
  `total_outstanding_bal` decimal(18,2) NULL COMMENT "Total
  outstanding balance",
  `total_tax_amount` decimal(18,2) NULL COMMENT "Total tax
  amount",
  `total_charges_amount` decimal(18,2) NULL COMMENT "Total 
  charges amount",
  `exchange_rate_applied` decimal(18,8) NULL COMMENT "FX rate
   applied",
  `transaction_cost` decimal(18,2) NULL COMMENT "Internal  
  cost of the transaction",
  `debit_credit_indicator` varchar(5) NULL COMMENT "D for
  Debit, C for Credit",
  `account_number` varchar(64) NULL COMMENT "Human-readable
  account number",
  `transaction_narrative` varchar(500) NULL COMMENT "Brief 
  description",
  `transaction_reference` varchar(100) NULL COMMENT "External
   reference",
  `contra_account_number` varchar(64) NULL COMMENT "Offsetting account",
  `journal_batch_id` largeint NULL COMMENT "Link to journal
  batch",
  `cheque_number` bigint NULL COMMENT "Cheque reference",
  `parent_transaction_id` largeint NULL COMMENT "Link to     
  original txn for reversals",
  `is_main_transaction` tinyint NULL COMMENT "Whether this is
   the main transaction leg",
  `record_status` varchar(20) NULL COMMENT "Active, Reversed,
   or Deleted",
  `backdate_status` varchar(20) NULL COMMENT "Backdate     
  processing status"
) ENGINE=OLAP
DUPLICATE KEY(`transaction_date`, `loan_account_id`, `loan_transaction_id`)
PARTITION BY RANGE(`transaction_date`)
