CREATE TABLE IF NOT EXISTS `fact_loan_transactions_enriched` (
  `transaction_date` date NOT NULL COMMENT "Official posting date (partition key)",
  `loan_account_id` largeint NOT NULL COMMENT "FK to dim_account",
  `loan_transaction_id` largeint NOT NULL COMMENT "Unique transaction ID",
  `account_number` varchar(64) NULL COMMENT "Public account number",
  `account_name` varchar(255) NULL COMMENT "Account name/title",
  `product_category` varchar(50) NULL COMMENT "Product category from dim_account",
  `product_sub_category` varchar(50) NULL COMMENT "Product sub-category from dim_account",
  `account_status_code` varchar(20) NULL COMMENT "Raw status code on the account",
  `account_status_description` varchar(100) NULL COMMENT "Human-readable account status",
  `customer_id` largeint NULL COMMENT "FK to dim_customer",
  `customer_number` varchar(64) NULL COMMENT "Business customer number",
  `customer_full_name` varchar(255) NULL COMMENT "Customer full name",
  `customer_category` varchar(100) NULL COMMENT "Customer category",
  `gender` varchar(10) NULL COMMENT "Customer gender",
  `customer_segment_id` int NULL COMMENT "Customer segment key",
  `origin_branch_id` int NULL COMMENT "Branch where transaction was initiated",
  `branch_name` varchar(255) NULL COMMENT "Branch name from dim_business_unit",
  `business_unit_type_description` varchar(100) NULL COMMENT "HO, Retail Branch, etc.",
  `urban_rural_classification` varchar(50) NULL COMMENT "Rural vs Urban",
  `currency_iso_code` varchar(10) NULL COMMENT "ISO currency code of the transaction",
  `product_id` varchar(64) NULL COMMENT "Product ID from dim_account",
  `product_code` varchar(30) NULL COMMENT "Product code from dim_product",
  `product_name_description` varchar(255) NULL COMMENT "Product name from dim_product",
  `product_type` varchar(100) NULL COMMENT "Product type from dim_product",
  `event_type_id` int NULL COMMENT "FK to dim_event",
  `event_code` varchar(50) NULL COMMENT "Event code e.g. 900, 901, 960",
  `event_description` varchar(255) NULL COMMENT "Event description",
  `event_category_code` varchar(50) NULL COMMENT "Event category code",
  `event_group_code` varchar(50) NULL COMMENT "Event group code",
  `value_date` date NULL COMMENT "Date for interest calculation",
  `journal_batch_id` largeint NULL COMMENT "transaction journal reference",
  `debit_credit_indicator` varchar(5) NULL COMMENT "D = Debit, C = Credit",
  `transaction_narrative` varchar(500) NULL COMMENT "Brief description",
  `transaction_reference` varchar(100) NULL COMMENT "External reference",
  `contra_account_number` varchar(64) NULL COMMENT "Offsetting account",
  `memo_type_code` int NULL COMMENT "Internal accounting memo classification",
  `channel_id` int NULL COMMENT "Channel key",
  `maker_user_id` int NULL COMMENT "Staff who captured the transaction",
  `checker_user_id` int NULL COMMENT "Staff who authorized the transaction",
  `is_main_transaction` tinyint NULL COMMENT "1 = main transaction leg",
  `parent_transaction_id` largeint NULL COMMENT "Link to original txn for reversals",
  `transaction_status_code` varchar(20) NULL COMMENT "Raw status code on the transaction",
  `transaction_status_description` varchar(100) NULL COMMENT "Human-readable transaction status",
  `backdate_status` varchar(20) NULL COMMENT "Backdate processing status",
  `principal_amount` decimal(18,2) NULL COMMENT "Principal component",
  `interest_amount` decimal(18,2) NULL COMMENT "Interest component",
  `insurance_amount` decimal(18,2) NULL COMMENT "Insurance component",
  `original_txn_amount` decimal(18,2) NULL COMMENT "Original transaction amount",
  `account_currency_amount` decimal(18,2) NULL COMMENT "Amount in account currency",
  `total_tax_amount` decimal(18,2) NULL COMMENT "Total tax amount",
  `total_charges_amount` decimal(18,2) NULL COMMENT "Total charges amount",
  `transaction_cost` decimal(18,2) NULL COMMENT "Internal cost of transaction",
  `exchange_rate_applied` decimal(18,8) NULL COMMENT "FX rate applied",
  `principal_remaining_bal` decimal(18,2) NULL COMMENT "Remaining principal after this txn",
  `total_outstanding_bal` decimal(18,2) NULL COMMENT "Total outstanding balance after this txn",
  `signed_amount` decimal(18,2) NULL COMMENT "account_currency_amount: positive for C, negative for D",
  `is_reversal` tinyint NULL COMMENT "1 = transaction is a reversal",
  `transaction_type_label` varchar(50) NULL COMMENT "Disbursement | Repayment - Principal | Repayment - Interest | Repayment - Insurance | Repayment - Unapplied Funds | Prepaid Interest | Late Payment Penalty | Fee & Charges | Interest Accrual | Write-Off | Write-Off Recovery | Reversal | Other",
  `loan_classification` varchar(30) NULL COMMENT "Classification from mapping_loan_classification at DPD=0 band",
  `loan_classification_code` tinyint NULL COMMENT "Numeric classification code",
  `is_npl` tinyint NULL COMMENT "1 = Non-Performing per mapping_loan_classification at DPD=0 band",
  `dw_refresh_ts` datetime NULL COMMENT "Timestamp of last DW load",
  INDEX idx_lt_txn_status (`transaction_status_code`) USING INVERTED,
  INDEX idx_lt_dc_indicator (`debit_credit_indicator`) USING INVERTED,
  INDEX idx_lt_event_code (`event_code`) USING INVERTED,
  INDEX idx_lt_event_cat (`event_category_code`) USING INVERTED,
  INDEX idx_lt_txn_type (`transaction_type_label`) USING INVERTED,
  INDEX idx_lt_is_reversal (`is_reversal`) USING INVERTED,
  INDEX idx_lt_is_npl (`is_npl`) USING INVERTED,
  INDEX idx_lt_branch (`branch_name`) USING INVERTED,
  INDEX idx_lt_prod_cat (`product_category`) USING INVERTED,
  INDEX idx_lt_prod_code (`product_code`) USING INVERTED
) ENGINE=OLAP
DUPLICATE KEY(`transaction_date`, `loan_account_id`, `loan_transaction_id`)
PARTITION BY RANGE(`transaction_date`)
