CREATE TABLE IF NOT EXISTS `fact_nisogeze_loans` (
  `balance_date` date NOT NULL COMMENT "The date of the balance snapshot",
  `source_system_id` varchar(64) NOT NULL COMMENT "Unique identifier from the Cilantro system",
  `account_number` varchar(64) NOT NULL COMMENT "The Nisogeze loan account number",
  `customer_name` varchar(255) NULL COMMENT "Customer name (useful if not yet linked to Dim_Customer)",
  `industry_sector` varchar(100) NULL COMMENT "Economic sector (Personal, Business, etc.)",
  `branch_name` varchar(100) NULL COMMENT "Name of the branch that issued the loan",
  `asset_classification` varchar(50) NULL COMMENT "Current risk grade (e.g., Loss, Doubtful, Substandard)",
  `loan_reference_text` varchar(100) NULL COMMENT "External reference number/contract ID",
  `mobile_number` varchar(50) NULL COMMENT "Contact number for collection purposes",
  `disbursement_date` date NULL COMMENT "The date funds were released",
  `maturity_date` date NULL COMMENT "The date the loan is due to be fully paid",
  `days_past_due` int NULL COMMENT "Number of days the loan is in arrears",
  `disbursed_amount` decimal(18,2) NULL COMMENT "The original loan amount granted",
  `outstanding_fees_amount` decimal(18,2) NULL COMMENT "Unpaid penalty or service fees",
  `total_interest_amount` decimal(18,2) NULL COMMENT "The total interest expected/charged",
  `processing_fee_amount` decimal(18,2) NULL COMMENT "Upfront fee charged at disbursement",
  `total_outstanding_balance` decimal(18,2) NULL COMMENT "Total amount due (Principal + Interest + Fees)",
  `provision_percentage` decimal(10,4) NULL COMMENT "The % of the balance held as a reserve (e.g., 1.00 for 100%)",
  `provision_amount` decimal(18,2) NULL COMMENT "The currency value of the risk provision",
  `risk_weighted_asset_pct` decimal(10,4) NULL COMMENT "Risk weighting for capital adequacy (RWA)",
  `risk_weighted_asset_amt` decimal(18,2) NULL COMMENT "Calculated Risk Weighted Asset value",
  INDEX idx_nisogeze_dpd (`days_past_due`) USING INVERTED,
  INDEX idx_nisogeze_class (`asset_classification`) USING INVERTED,
  INDEX idx_nisogeze_balance_date (`balance_date`) USING INVERTED
) ENGINE=OLAP
UNIQUE KEY(`balance_date`, `source_system_id`, `account_number`)
DISTRIBUTED BY HASH(`account_number`) BUCKETS 4
PROPERTIES (
"replication_allocation" = "tag.location.default: 1",
"min_load_replica_num" = "-1",
"is_being_synced" = "false",
"storage_medium" = "hdd",
"storage_format" = "V2",
"inverted_index_storage_format" = "V1",
"compression" = "ZSTD",
"enable_unique_key_merge_on_write" = "true",
"light_schema_change" = "true",
"disable_auto_compaction" = "false",
"enable_single_replica_compaction" = "false",
"group_commit_interval_ms" = "10000",
"group_commit_data_bytes" = "134217728",
"enable_mow_light_delete" = "false"
);
CREATE TABLE IF NOT EXISTS `fact_nivusheplus_loans` (
  `loan_id` varchar(64) NOT NULL COMMENT "Unique identifier for the NivushePlus record",
  `account_id` varchar(64) NOT NULL COMMENT "The primary loan account identifier",
  `product_code` varchar(50) NULL COMMENT "e.g., TCB.D2000_PG007",
  `loan_status` varchar(20) NULL COMMENT "e.g., Partial, Settled, Active",
  `asset_classification` varchar(50) NULL COMMENT "Risk grade: Loss, Doubtful, Substandard, etc.",
  `industry_sector` varchar(50) NULL COMMENT "Economic sector (Personal, Business)",
  `principal_paid_amount` decimal(18,2) NULL COMMENT "Total principal recovered to date",
  `interest_paid_amount` decimal(18,2) NULL COMMENT "Total interest recovered to date",
  `penalty_paid_amount` decimal(18,2) NULL COMMENT "Total penalties/late fees recovered",
  `total_recovered_amount` decimal(18,2) NULL COMMENT "Sum of Principal + Interest + Penalty paid",
  `disbursed_amount` decimal(18,2) NULL COMMENT "The original principal amount granted",
  `principal_outstanding_bal` decimal(18,2) NULL COMMENT "Remaining principal to be recovered",
  `interest_outstanding_bal` decimal(18,2) NULL COMMENT "Remaining interest to be recovered",
  `penalty_outstanding_bal` decimal(18,2) NULL COMMENT "Remaining penalties to be recovered",
  `total_outstanding_balance` decimal(18,2) NULL COMMENT "The total current debt (Principal + Int + Pen)",
  `gross_exposure_amount` decimal(18,2) NULL COMMENT "Total exposure before provisions",
  `days_past_due` int NULL COMMENT "Vital metric: Days Past Due",
  `loan_tenure_days` int NULL COMMENT "Total duration of the loan in days",
  `risk_weighted_asset_pct` decimal(10,4) NULL COMMENT "Regulatory risk weight",
  `risk_weighted_asset_amt` decimal(18,2) NULL COMMENT "Final RWA calculation for capital",
  `loan_disbursement_date` date NULL COMMENT "Date the loan was issued",
  `last_repayment_date` date NULL COMMENT "Most recent date a payment was received",
  `maturity_date` date NULL COMMENT "Final date the loan is expected to be paid",
