  `balance_date` date NOT NULL COMMENT "The date of the balance snapshot",
  `account_number` varchar(64) NOT NULL COMMENT "The unique Pension Advance account number",
  `customer_number_rubikon` largeint NOT NULL COMMENT "The link back to the Rubikon dim_customer",
  `customer_name` varchar(255) NULL COMMENT "Name for quick reference/verification",
  `branch_name` varchar(100) NULL COMMENT "Branch where the advance was issued",
