CREATE TABLE IF NOT EXISTS `fact_pha_alerts` (
  `alert_id` largeint NOT NULL COMMENT "Unique primary identifier for the alert record",
  `alert_date` date NOT NULL COMMENT "Date the alert was triggered",
  `transaction_id` largeint NULL COMMENT "Link to fact_gl_transactions for the source txn",
  `customer_id` largeint NULL COMMENT "Refers to dim_customer",
  `branch_id` largeint NULL COMMENT "Refers to dim_business_unit",
  `alert_scheme_id` int NULL COMMENT "Pricing scheme applied to this alert",
  `charge_id` int NULL COMMENT "Internal fee configuration ID",
  `alert_time` datetime NULL COMMENT "Time the alert was triggered",
  `alert_event_code` varchar(20) NULL COMMENT "Alert event code (e.g., 'TXN_DR' for Debit, 'LOGIN' for access)",
  `alert_type` varchar(10) NULL COMMENT "Alert type (SMS, EMAIL, or PUSH)",
  `transaction_date` date NULL COMMENT "The date of the actual financial transaction",
  `account_number` varchar(64) NULL COMMENT "The account involved in the alert",
  `contra_account_no` varchar(64) NULL COMMENT "The receiving/offsetting account number",
  `currency_code` varchar(3) NULL COMMENT "Currency of the transaction",
  `transaction_amount` decimal(18,2) NULL COMMENT "Value of the transaction that triggered the alert",
  `transaction_charge` decimal(18,2) NULL COMMENT "Fee charged to the customer for the alert",
  `transaction_description` text NULL COMMENT "The actual content sent to the customer",
  `cleared_balance_after` decimal(18,2) NULL COMMENT "Account balance displayed in the alert message",
  `charge_gl_account` varchar(64) NULL COMMENT "The GL account where the alert fee was posted",
  `system_cost_amount` decimal(18,2) NULL COMMENT "The cost to the bank for sending the SMS/Email",
  `mobile_or_email` varchar(255) NULL COMMENT "The target phone number or email address",
  `system_originator` varchar(100) NULL COMMENT "The subsystem that generated the alert",
