CREATE TABLE IF NOT EXISTS `fact_transaction_journal` (
  `journal_id` largeint NOT NULL COMMENT "Primary unique ID for the journal entry",
  `transaction_date` date NOT NULL COMMENT "Official posting date",
  `source_account_id` largeint NOT NULL COMMENT "The primary account being debited/credited",
  `event_id` int NULL COMMENT "Link to dim_event (Withdrawal, Deposit, etc.)",
  `event_code` varchar(50) NULL COMMENT "Event code identifier",
  `source_account_number` varchar(64) NULL COMMENT "Source account number",
  `batch_reference_id` largeint NULL COMMENT "Groups multiple journals (e.g., Salary upload)",
  `reversal_journal_id` largeint NULL COMMENT "Link to the journal entry that reversed this",
  `account_currency_id` int NULL COMMENT "Currency of the primary account",
  `account_product_id` int NULL COMMENT "Link to dim_product",
  `contra_account_no` varchar(64) NULL COMMENT "The account on the other side of the entry",
  `contra_branch_id` int NULL COMMENT "Branch of the contra account",
  `origin_branch_id` int NULL COMMENT "Branch where the txn was initiated",
  `checker_user_id` int NULL COMMENT "Staff who authorized the txn",
  `maker_user_id` int NULL COMMENT "Staff who captured the txn",
  `channel_id` int NULL COMMENT "Link to dim_channel",
  `source_of_funds_id` int NULL COMMENT "AML classification for source of cash",
  `profit_center_id` int NULL COMMENT "Accounting responsibility center",
  `vault_depot_id` int NULL COMMENT "Links to specific cash drawers/vaults",
  `value_date` date NULL COMMENT "Date for interest/accounting value",
  `transaction_narrative` varchar(500) NULL COMMENT "Human-readable description",
  `transaction_reference` varchar(100) NULL COMMENT "External reference/slip number",
  `counterparty_name` varchar(255) NULL COMMENT "Name of the person at the counter",
  `channel_external_ref` varchar(100) NULL COMMENT "Reference from Mobile/ATM/Switch",
  `callover_status` varchar(20) NULL COMMENT "Quality assurance status for the txn",
  `transaction_amount` decimal(18,2) NULL COMMENT "Amount in original transaction currency",
  `account_amount` decimal(18,2) NULL COMMENT "Amount in local account currency",
  `total_charges` decimal(18,2) NULL COMMENT "Sum of all fees applied to this txn",
  `total_taxes` decimal(18,2) NULL COMMENT "Sum of all taxes (VAT/Duty) applied",
  `local_ccy_equivalent` decimal(18,2) NULL COMMENT "Amount converted to the banks base currency",
  `internal_txn_cost` decimal(18,2) NULL COMMENT "Operational cost to the bank",
  `custom_date_fields` date NULL COMMENT "Flexible slots for specific product dates",
  `custom_numeric_fields` decimal(18,2) NULL COMMENT "Flexible slots for specific product values",
  `custom_text_fields` varchar(255) NULL COMMENT "Flexible slots for custom identifiers",
  `debit_credit_indicator` varchar(5) NULL COMMENT "D for Debit, 'C' for Credit",
  `is_main_transaction` tinyint NULL COMMENT "1 if this is the primary entry leg",
  `is_reversed_flag` tinyint NULL COMMENT "1 if this transaction was reversed",
  `is_signature_checked` tinyint NULL COMMENT "Audit flag for teller verification",
  `record_status` varchar(20) NULL COMMENT "A (Active), 'P' (Pending), 'R' (Reversed)",
  `created_date` date NULL COMMENT "Date the record was created",
  `created_by` varchar(100) NULL COMMENT "User who created the record",
  `user_id` varchar(100) NULL COMMENT "User identifier",
  INDEX idx_journal_event (`event_id`) USING INVERTED,
  INDEX idx_journal_account (`source_account_id`) USING INVERTED,
  INDEX idx_journal_branch (`origin_branch_id`) USING INVERTED,
  INDEX idx_journal_channel (`channel_id`) USING INVERTED,
  INDEX idx_journal_status (`record_status`) USING INVERTED,
  INDEX idx_journal_dr_cr (`debit_credit_indicator`) USING INVERTED,
  INDEX idx_journal_reversed (`is_reversed_flag`) USING INVERTED
) ENGINE=OLAP
DUPLICATE KEY(`journal_id`, `transaction_date`, `source_account_id`)
PARTITION BY RANGE(`transaction_date`)
(PARTITION p2018 VALUES [('0000-01-01'), ('2019-01-01')),
PARTITION p2019 VALUES [('2019-01-01'), ('2020-01-01')),
PARTITION p2020 VALUES [('2020-01-01'), ('2021-01-01')),
PARTITION p2021 VALUES [('2021-01-01'), ('2022-01-01')),
PARTITION p2022 VALUES [('2022-01-01'), ('2023-01-01')),
