CREATE TABLE IF NOT EXISTS `fact_wakala_transactions` (
  `wakala_txn_id` largeint NOT NULL COMMENT "Source system ID (transactions.id)",
  `created_date` datetime NOT NULL COMMENT "Transaction creation timestamp (partition key)",
  `initiated_date` datetime NULL COMMENT "Transaction initiation timestamp",
  `completed_date` datetime NULL COMMENT "Transaction completion/settlement timestamp",
  `msisdn` varchar(255) NULL COMMENT "Agent MSISDN initiating the transaction",
  `agent_operator_msisdn` varchar(255) NULL COMMENT "Operator MSISDN if different from agent owner",
  `branch_code` varchar(255) NULL COMMENT "Link to dim_business_unit",
  `till_number` varchar(255) NULL COMMENT "Agent till/POS number",
  `customer_name` varchar(255) NULL,
  `depositor_name` varchar(255) NULL,
  `sender_name` varchar(255) NULL,
  `beneficiary_name` varchar(255) NULL,
  `source_account` varchar(255) NULL COMMENT "Debit/source account number (sourceAcct)",
  `destination_account` varchar(255) NULL COMMENT "Credit/destination account number (destinationAcct)",
  `pan` varchar(255) NULL COMMENT "Card PAN — must be masked/tokenised before loading",
  `amount` decimal(18,2) NULL COMMENT "Principal transaction amount",
  `charge` decimal(18,2) NULL COMMENT "Total fee charged to customer",
  `agent_commission` decimal(18,2) NULL COMMENT "Commission earned by agent (agentComission)",
  `bank_commission` decimal(18,2) NULL COMMENT "Bank revenue share (bankComission)",
  `value_added_tax` decimal(18,2) NULL COMMENT "VAT on fees (valueAddedTax)",
  `exercise_duty` decimal(18,2) NULL COMMENT "Excise/exercise duty applied (exerciseDuty)",
  `cust_available_balance` varchar(255) NULL COMMENT "Customer available balance after transaction",
  `cust_ledger_balance` varchar(255) NULL COMMENT "Customer ledger balance after transaction",
  `currency` varchar(255) NULL,
  `txn_type` varchar(255) NULL COMMENT "e.g., CASH_IN, CASH_OUT, TRANSFER, BILL_PAY, AIRTIME",
  `channel` varchar(255) NULL COMMENT "Originating channel name",
  `channel_id` varchar(255) NULL COMMENT "Originating channel ID",
  `pay_option` varchar(255) NULL COMMENT "Payment option selected by customer",
  `processing_code` varchar(255) NULL COMMENT "Internal operation processing code",
  `reference` varchar(255) NULL COMMENT "Agent-generated transaction reference",
  `receipt` varchar(255) NULL COMMENT "System-generated receipt number",
  `row_id` varchar(255) NULL COMMENT "Idempotency/deduplication row identifier",
  `control_number` varchar(255) NULL COMMENT "Government/GePG control number for bill payments",
  `gepg_payment_channel` varchar(255) NULL COMMENT "GePG payment channel identifier",
  `switch_reference` varchar(255) NULL COMMENT "Interbank switch reference number",
  `sender_institution_code` varchar(255) NULL COMMENT "Interbank sender institution code",
  `ben_institution_code` varchar(255) NULL COMMENT "Interbank beneficiary institution code",
  `pan_code` varchar(255) NULL COMMENT "Card scheme/BIN code",
  `units` varchar(255) NULL COMMENT "Units purchased (airtime, electricity)",
  `token` varchar(255) NULL COMMENT "Prepaid token generated for customer",
  `status` varchar(255) NULL COMMENT "Final transaction status (SUCCESS, FAILED, PENDING, REVERSED)",
  `status_description` varchar(255) NULL,
  `cbs_status` varchar(255) NULL COMMENT "Core banking system processing status",
  `cbs_remarks` varchar(255) NULL,
  `third_party_status` varchar(255) NULL COMMENT "Third-party/switch processing status",
  `third_party_remarks` varchar(255) NULL,
  `response_code` varchar(255) NULL COMMENT "Response code from switch or CBS",
  `reversal_status` varchar(255) NULL COMMENT "Reversal status (PENDING, COMPLETED, FAILED)",
  `reversal_reference` varchar(255) NULL,
  `reversal_reason` varchar(255) NULL,
  `device_id` varchar(255) NULL,
  `imsi` varchar(255) NULL COMMENT "SIM card IMSI number",
  `source_ip` varchar(255) NULL,
  `source_node` varchar(255) NULL,
  `narration` varchar(255) NULL COMMENT "Transaction description/narrative",
  `rec_status` varchar(255) NULL,
  INDEX idx_wakala_txn_type (`txn_type`) USING INVERTED,
  INDEX idx_wakala_txn_status (`status`) USING INVERTED,
  INDEX idx_wakala_txn_cbs_status (`cbs_status`) USING INVERTED,
  INDEX idx_wakala_txn_reversal (`reversal_status`) USING INVERTED,
  INDEX idx_wakala_txn_branch (`branch_code`) USING INVERTED,
  INDEX idx_wakala_txn_channel (`channel`) USING INVERTED,
  INDEX idx_wakala_txn_third_party (`third_party_status`) USING INVERTED,
  INDEX idx_wakala_txn_msisdn (`msisdn`) USING INVERTED
) ENGINE=OLAP
DUPLICATE KEY(`wakala_txn_id`, `created_date`)
PARTITION BY RANGE(`created_date`)
